-- ============================================================
-- V1.61: 手工DIY种子Q&A (5个二级分类 × 30条 = 150条)
-- 一级分类: 手工DIY (handcraft_diy)
-- 二级分类:
--   1. handcraft_materials  - 手工材料 (毛线/布料/串珠/粘土/颜料/画笔)
--   2. handcraft_products   - 手工成品 (手作/DIY/定制/手工/礼物/创意)
--   3. handcraft_knitting   - 编织工艺 (编织/钩针/毛衣/围巾/玩偶/抱枕)
--   4. handcraft_ceramic    - 陶艺作品 (陶艺/陶瓷/手工/花瓶/杯子/摆件)
--   5. handcraft_wood       - 木工作品 (木工/木质/手工/家具/摆件/模型)
--
-- 数据特点:
--   - 真实闲鱼手工DIY买卖场景问答
--   - 涵盖: 材质、是否原创、是否可定制、保养、工期、包装、是否含工具、教程
--   - 回复专业有温度，体现销冠话术技巧
--   - score 70-95, tags 3-5个, source_summary 一句话
--   - answer 200-500字
--
-- 技术说明:
--   - content_hash 由 MD5(question+answer) 生成，确保唯一
--   - vector_indexed=1 标记已建立向量索引
--   - learn_batch_id='seed-v1.61' 标识本批次种子数据
--   - source_type='seed' 标识为种子数据(非对话学习)
--   - 通过 JOIN ai_cs_kb_category 关联分类ID
--
-- 日期: 2026-07-28
-- ============================================================

-- ============ 1. 手工材料 handcraft_materials (30条) ============
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.61', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'handcraft_materials' AS code, '这款毛线是什么材质的？中粗还是细线？适合新手吗' AS question, '亲，这款是100%牛奶棉毛线，属于中粗线哦，适合织毛衣、围巾、帽子这类保暖款。牛奶棉手感柔软亲肤，织出来的成品蓬松有弹性，不起球不扎人。一团是100g，根据您织的款式不同，一般毛衣需要8到10团，围巾2到3团就够了。新手也容易上手，线质顺滑不易劈线。如果您是第一次织，我可以推荐几款简单图解给您参考，有任何问题随时问我哈，包教包会直到您做出满意的作品' AS answer, '毛线,材质,中粗,牛奶棉,新手' AS tags, '买家咨询毛线材质规格及新手适用性' AS source_summary, 88 AS score
  UNION ALL SELECT 'handcraft_materials', '一团毛线有多少克？织一件毛衣大概要几团？', '亲，我们这款毛线一团是100g标准装哦。织女士毛衣一般需要8到10团，男士加大的话10到12团，儿童款4到6团就够了。如果是织围巾的话2到3团，帽子1到2团即可。建议您购买时多备1到2团，避免不够用时出现色差问题，多出来的线也可以织个小物件配套哦。现在购买满5团包邮，还送钩针一枚，需要的亲可以直接拍下哈，量大还可以咨询客服拿批发价更优惠' AS answer, '毛线,克重,用量,包邮,赠品' AS tags, '买家咨询毛线克重及用量估算' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_materials', '这个毛线会不会起球？洗了会变形吗？', '亲，这款牛奶棉毛线经过特殊工艺处理，正常穿着和洗涤是不易起球的哦。建议手洗或机洗套洗衣袋，水温不超过30度，平铺晾干即可保持原型。千万不要用力拧绞或者暴晒，这样能延长使用寿命。相比普通腈纶线，牛奶棉的耐磨性和抗起球性都更好，织出来的毛衣穿一两个季度依然平整有型。如果您还有其他洗涤保养疑问，随时问我哈，我会详细为您解答，让您的手作作品陪伴更久' AS answer, '毛线,起球,洗涤,保养,牛奶棉' AS tags, '买家咨询毛线起球及洗涤保养方法' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_materials', '这块布料是什么成分的？纯棉还是混纺？', '亲，这款是100%纯棉布料哦，没有添加任何化纤成分，亲肤透气不刺激皮肤，特别适合做贴身衣物、婴儿用品和手工布艺。纯棉布料吸湿性好，染色均匀不易掉色，做出来的成品质感高级。幅宽是110cm，有多种花色可选，适合做拼布、包包、玩偶、围裙等。如果您需要做大批量的手作，可以咨询客服拿批发价哦，量大的话价格更优惠，还有同系列花色可以搭配使用' AS answer, '布料,纯棉,成分,幅宽,亲肤' AS tags, '买家咨询布料成分及用途' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_materials', '布料的幅宽是多少？一码大概多大？', '亲，这款布料幅宽是110cm，一码的尺寸是110cm乘以91cm哦。做一个小书包大概需要1.5码，做拼布被的话根据图案复杂程度一般需要5到8码。建议您购买时多预留10%的损耗量，方便裁剪时调整。我们还有多款同系列花色可以搭配使用，做出来的拼布作品更有层次感。现在下单当天发货，江浙沪包邮，其他地区满50元也包邮哦，有什么用量问题也可以咨询我帮您估算' AS answer, '布料,幅宽,尺寸,用量,包邮' AS tags, '买家咨询布料幅宽及用量计算' AS source_summary, 82 AS score
  UNION ALL SELECT 'handcraft_materials', '这个布料会掉色吗？第一次洗需要注意什么？', '亲，我们这款纯棉布料采用活性染料染色，色牢度达到4级以上，正常洗涤不会掉色哦。第一次洗的时候建议用冷水单独清洗，加少许盐固色效果更好。避免使用漂白剂和含酶洗衣液，不要长时间浸泡。晾晒时反面晾干，避免阳光直射导致褪色。如果您做的是拼布作品，不同颜色布料建议分别预洗一次再裁剪，这样能避免后期串色问题。有任何手作问题都可以问我哈，帮您避坑不踩雷' AS answer, '布料,掉色,固色,洗涤,纯棉' AS tags, '买家咨询布料掉色及首次洗涤注意事项' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_materials', '这些串珠是玻璃的还是塑料的？质感怎么样？', '亲，我们这款串珠是优质亚克力材质哦，透明度和光泽度都接近玻璃珠，但重量更轻、不易碎，适合做各种手链、项链、手机链等饰品。相比塑料珠，亚克力珠质感更高级，表面光滑无毛刺，颜色饱满不褪色。每包约100颗，直径有6mm、8mm、10mm三种规格可选。如果您需要做大批量饰品，可以咨询批发价哦，还有配套的弹力线和工具套装可以一起带走，一站式购齐更方便' AS answer, '串珠,亚克力,材质,规格,饰品' AS tags, '买家咨询串珠材质及规格选择' AS source_summary, 83 AS score
  UNION ALL SELECT 'handcraft_materials', '串珠有多大？做手链的话用多大合适？', '亲，串珠有6mm、8mm、10mm三种规格哦。做女士手链推荐8mm，约需20到25颗；做男士手链推荐10mm，约需18到22颗；做儿童手链推荐6mm，约需15到20颗。如果您想做多层缠绕手链，6mm的效果会更精致。每包100颗，足够做4到5条手链。我们还有配套的3mm弹力线出售，穿珠更方便。新手建议先从8mm练手，大小适中好操作，做出来成品也很好看哦，有任何搭配问题随时问我' AS answer, '串珠,尺寸,手链,用量,新手' AS tags, '买家咨询串珠尺寸及手链用量推荐' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_materials', '串珠的颜色和图片一样吗？会有色差吗？', '亲，我们的串珠都是实物拍摄，但不同显示器会有轻微色差哦。如果您对颜色要求比较高，可以先拍一包混合色试用，满意后再回购单色装。目前有30多种颜色可选，热门的樱花粉、雾霾蓝、香槟金都很受欢迎。做手链的话建议选择3到5个相近色系搭配，效果更协调。如果搭配不好看也可以退换哦，我们支持7天无理由，让您买得放心，选色纠结的话我也可以帮您推荐搭配方案' AS answer, '串珠,颜色,色差,搭配,退换' AS tags, '买家咨询串珠颜色色差及搭配建议' AS source_summary, 82 AS score
  UNION ALL SELECT 'handcraft_materials', '这个粘土是超轻粘土还是树脂粘土？干透后是什么效果？', '亲，这款是超轻粘土哦，干透后会有轻微膨大，质地轻盈不变形，适合做玩偶、摆件、发卡等。相比树脂粘土，超轻粘土更易塑形、干后可上色，但防水性稍弱。干透时间根据作品大小约6到24小时，完全干透后表面可以用水性丙烯颜料上色，再喷一层亮油就能防水防尘啦。一包50g可以做好几个小作品，性价比很高。新手也能轻松上手，做出可爱的萌物哦，有教程赠送' AS answer, '粘土,超轻,干燥,上色,新手' AS tags, '买家咨询粘土类型及干燥效果' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_materials', '粘土做完多久能干？能不能用吹风机加速？', '亲，超轻粘土自然干燥一般6到24小时，具体看作品大小和厚度哦。小件作品6到8小时就能干透，大件或厚实的作品建议自然晾干24小时以上。可以用吹风机冷风档加速表面干燥，但不要用热风，容易导致表面开裂或变形。干透后作品会变轻、按压无凹陷即可。做好的作品建议放在阴凉通风处保存，避免阳光直射和潮湿环境，这样能保存更久哦。有什么制作问题随时问我，帮您做出完美作品' AS answer, '粘土,干燥,吹风机,保养,开裂' AS tags, '买家咨询粘土干燥时间及加速方法' AS source_summary, 83 AS score
  UNION ALL SELECT 'handcraft_materials', '粘土干透后需要上色吗？用什么颜料比较好？', '亲，超轻粘土本身有12种基础色，可以通过混色调出大部分颜色，简单作品不需要额外上色哦。如果您想做更精细的效果，干透后可以用水性丙烯颜料上色，覆盖力好且防水。上色后建议喷一层亮油或光油，既能保护颜色又能增加光泽度，让作品更精致。我们店里有配套的丙烯颜料和亮油套装，一起购买更划算。新手建议先从混色开始练习，熟练后再尝试上色技巧，循序渐进更有成就感' AS answer, '粘土,上色,丙烯,亮油,混色' AS tags, '买家咨询粘土上色及颜料选择' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_materials', '这个丙烯颜料环保吗？小孩子能用吗？', '亲，我们这款是环保水性丙烯颜料，通过SGS检测认证，无毒无异味，儿童可以在大人陪同下使用哦。颜料采用进口色粉，色彩饱和度高、覆盖力强，干后防水不脱落，适合画在画布、木头、石头、布料等多种材质上。一套12色满足大部分绘画需求，还附赠调色盘和画笔。建议使用时穿旧衣物或戴围裙，避免颜料沾到衣服上不好清洗。3岁以下宝宝建议不要接触，避免误食哦，安全第一' AS answer, '颜料,环保,儿童,丙烯,无毒' AS tags, '买家咨询颜料环保性及儿童使用安全' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_materials', '丙烯颜料画完之后防水吗？能不能洗？', '亲，丙烯颜料干透后是完全防水的哦，遇水不会融化或掉色，所以画在帆布包、T恤、鞋子上都可以正常清洗。建议干透24小时后再水洗，手洗冷水即可，不要用力搓揉画面部分。如果是画在室外物品上，建议再刷一层户外清漆保护，能防晒防雨延长寿命。颜料一旦干在衣服或皮肤上就比较难清洗，使用时建议做好防护。画错未干时可以用湿纸巾擦掉重新画哦，大胆创作不怕出错' AS answer, '颜料,防水,清洗,丙烯,保护' AS tags, '买家咨询丙烯颜料防水性能及清洗' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_materials', '颜料覆盖力怎么样？深色布料上能画吗？', '亲，这款丙烯颜料覆盖力很强哦，深色布料上也能画出鲜艳的颜色，一般涂2到3层就能完全覆盖底色。建议第一层薄涂打底，等干透后再涂第二层，这样颜色更均匀饱满。白色和黄色的覆盖力最佳，其他深色系覆盖力稍弱，可以先打白底再上色。画在黑色帆布包上效果特别惊艳，适合做个性化定制。如果觉得颜色不够浓，可以少加水直接用原色涂抹，覆盖效果会更好哦，画出属于您的专属作品' AS answer, '颜料,覆盖力,深色,布料,丙烯' AS tags, '买家咨询颜料覆盖力及深色应用' AS source_summary, 83 AS score
  UNION ALL SELECT 'handcraft_materials', '画笔是什么材质的？尼龙还是动物毛？', '亲，我们这款画笔是高级尼龙毛材质哦，弹性和吸水性都接近狼毫，但更耐用不易掉毛。尼龙笔适合画丙烯和水粉，笔触顺滑、回弹好、易清洗，是手作爱好者的入门首选。一套6支包含不同型号，从勾线到大面积涂色都能覆盖。相比动物毛笔，尼龙笔更经济实惠，新手用也不心疼。建议使用后及时用清水冲洗，顺着笔毛方向整理，晾干后收纳能延长使用寿命哦，保养得当可以用半年以上' AS answer, '画笔,尼龙,材质,弹性,套装' AS tags, '买家咨询画笔材质及特点' AS source_summary, 82 AS score
  UNION ALL SELECT 'handcraft_materials', '画笔的弹性怎么样？勾线会分叉吗？', '亲，这款尼龙画笔弹性很好哦，按压后能迅速回弹，勾线时笔尖聚拢不分叉，画出来的线条流畅细腻。勾线笔选用高弹尼龙丝，笔尖经过特殊处理，长时间使用也不易变形。建议使用时不要用力过猛，颜料稠度适中，这样画出来的线条更顺滑。使用后及时清洗、整理笔尖晾干，能保持笔锋锐利。如果您是画细节比较多，推荐搭配000号和00号勾线笔，精细度更高哦，画出专业级作品' AS answer, '画笔,弹性,勾线,分叉,保养' AS tags, '买家咨询画笔弹性及勾线效果' AS source_summary, 83 AS score
  UNION ALL SELECT 'handcraft_materials', '画笔会不会掉毛？用久了会变形吗？', '亲，我们这款画笔采用加固笔头工艺，正常使用是不易掉毛的哦。新笔第一次使用时可能有1到2根浮毛，这是正常现象，用清水润湿后轻轻梳理即可。使用时避免长时间浸泡在水中，不要用力拧绞笔毛，这样能延长使用寿命。清洗时用温水冲洗到水变清澈，顺着毛流整理，悬挂晾干。保养得当的话，一支笔可以用半年以上。如果出现掉毛严重的情况，可以联系客服补发哦，售后有保障让您放心' AS answer, '画笔,掉毛,保养,清洗,耐用' AS tags, '买家咨询画笔掉毛及耐用性' AS source_summary, 81 AS score
  UNION ALL SELECT 'handcraft_materials', '这套手工工具都包含什么？新手够用吗？', '亲，这款手工工具套装包含12件套：剪刀、镊子、锥子、顶针、拆线器、缝纫针、珠针、软尺、划粉、穿线器、钩针、收纳包，新手入门完全够用哦。每件工具都经过精心挑选，质量过硬，能满足大部分手作场景：缝纫、编织、串珠、布艺都能覆盖。收纳包方便整理携带，不占地方。单买这些工具要100多元，套装只要59元，性价比超高。如果后期想进阶，还可以单独补充专业工具哦' AS answer, '工具,套装,新手,缝纫,编织' AS tags, '买家咨询工具套装内容及新手适用性' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_materials', '材料包里有没有教程？新手能看懂吗？', '亲，我们的材料包都配有详细图文教程和视频教程哦，新手也能轻松上手。教程包含材料清单、工具使用说明、分步骤图解、常见问题解答，每个步骤都有高清实拍图，跟着做就行。视频教程扫码即可观看，老师讲解细致，还会分享一些实用小技巧。如果您做到某一步卡住了，随时可以联系客服一对一指导，保证您能完成作品。我们店还有新手交流群，可以和其他手友一起学习进步哦，入坑不孤单' AS answer, '材料包,教程,新手,视频,指导' AS tags, '买家咨询材料包教程及新手指导' AS source_summary, 88 AS score
  UNION ALL SELECT 'handcraft_materials', '我想买多一些材料，有批发价吗？', '亲，当然有批发价哦！满10件享9折，满30件享8折，满50件享7折，量大还有专属优惠。如果您是工作室或者做手作售卖的，可以联系客服报备老客户，后续享受专属批发价和优先发货。我们还有会员积分制度，每次购买都能攒积分，积分可以抵现或兑换工具。材料都是现货充足，一般下单24小时内发货，大批量也可以安排分批发货哦。需要的话可以直接拍下，备注您的需求，给您最优惠的价格' AS answer, '批量,优惠,批发,会员,发货' AS tags, '买家咨询批量购买优惠及批发价' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_materials', '这些材料买回来怎么保存？能放多久？', '亲，不同材料保存方法不同哦。毛线建议密封袋装好放阴凉处，避免受潮和虫蛀，可以放一包干燥剂，能保存2到3年。布料折叠平整放干燥处，避免暴晒褪色。粘土开封后要密封保存，防止干硬，建议用保鲜膜包紧再装密封袋，能放6到12个月。颜料密封存放避免高温冰冻，能保存1到2年。画笔清洗晾干后平放或悬挂。总之避光、防潮、密封是关键，正确保存材料不浪费哦，有疑问随时问我' AS answer, '保存,材料,防潮,密封,保质期' AS tags, '买家咨询各类材料保存方法及保质期' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_materials', '我是新手，想学手工，有什么材料推荐？', '亲，欢迎入手作坑哦！新手推荐从简单的串珠手链或超轻粘土入门，材料少、易上手、成就感强。串珠手链材料包只要19.9元，包含珠子、弹力线、教程，1小时就能做出一条漂亮手链。粘土入门包29.9元，可以做3到4个小摆件。如果您喜欢布艺，推荐布艺小包材料包，39.9元包含布料、针线、教程，做出来实用又好看。这些都是零基础友好，跟着教程一步步做，保证能做出满意的作品' AS answer, '新手,推荐,入门,材料包,串珠' AS tags, '新手咨询入门材料推荐' AS source_summary, 89 AS score
  UNION ALL SELECT 'handcraft_materials', '这些材料小孩子能用吗？安全吗？', '亲，我们的材料大部分适合6岁以上儿童在大人陪同下使用哦。超轻粘土和串珠是儿童热门选择，材料无毒环保，能锻炼孩子动手能力和创造力。剪刀建议使用儿童安全剪刀，圆润不伤手。丙烯颜料是环保水性，但建议3岁以下宝宝不要接触，避免误食。材料包里的小零件较多，使用时家长要留意，避免孩子放入口鼻。我们有专门的儿童手作材料包系列，安全性和趣味性都经过专门设计，可以看看哦' AS answer, '儿童,安全,材料,陪同,无毒' AS tags, '买家咨询材料儿童安全性' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_materials', '这些材料是国产的还是进口的？质量有保障吗？', '亲，我们的材料大部分是国产优质品牌，部分高端系列是进口的哦。国产材料近年质量提升很大，性价比很高，完全能满足日常手作需求。每批材料入库前都会做质量检测，确保色牢度、环保性、耐用性达标才发货。如果您对品质有更高要求，也有进口系列可选，比如日本进口的钩针线、德国进口的丙烯颜料等。所有材料都支持7天无理由退换，质量问题包退包换，让您买得放心哦' AS answer, '产地,国产,进口,质量,退换' AS tags, '买家咨询材料产地及质量保障' AS source_summary, 83 AS score
  UNION ALL SELECT 'handcraft_materials', '毛线有多少种颜色？能指定混色发货吗？', '亲，这款毛线目前有40多种颜色哦，涵盖基础色系、马卡龙色系、莫兰迪色系，热门的奶白、燕麦、雾霾蓝、藕粉都有现货。可以指定颜色混搭发货，拍下时备注您需要的颜色编号即可。如果不确定选什么颜色，推荐几款百搭色：奶白、燕麦、浅灰、豆沙色，怎么搭配都好看。织毛衣的话推荐同色系深浅搭配，织围巾可以撞色拼接，效果都很出片。颜色选择困难的话，可以咨询客服帮您推荐哦' AS answer, '颜色,选择,混色,搭配,现货' AS tags, '买家咨询毛线颜色及混色发货' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_materials', '粘土有几种规格？买哪种合适？', '亲，粘土有3种规格可选哦。小包50g适合试色或做小件，2到3种颜色搭配就够了。中包100g最热门，能做5到6个中型作品，性价比最高。大包250g适合工作室或批量制作，量大更优惠。新手建议先买小包试手感，满意后再回购大包。颜色方面推荐基础12色套装，能混出大部分需要的颜色。如果做特定主题，比如多肉、动物，也有主题色套装可选，搭配更专业。有任何问题随时问我' AS answer, '粘土,规格,选择,套装,用量' AS tags, '买家咨询粘土规格及选择建议' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_materials', '材料是现货吗？什么时候发货？', '亲，店内材料基本都是现货哦，下单后24小时内发货，一般下午4点前的订单当天发出。如果遇到库存紧张或者预售款，会在商品详情页标注预计发货时间。江浙沪一般1到2天到，其他地区2到4天，偏远地区可能5到7天。如果您有加急需求，可以联系客服发顺丰，差价自理。大批量订单可能需要分批发货，客服会和您沟通确认。发货后会有物流单号，您可以随时查询进度哦' AS answer, '发货,现货,时间,物流,加急' AS tags, '买家咨询发货时间及物流时效' AS source_summary, 82 AS score
  UNION ALL SELECT 'handcraft_materials', '运费怎么算？包邮条件是什么？', '亲，江浙沪满35元包邮，其他地区满50元包邮，不满的话运费5到12元根据地区不同。大件或重物可能需要补差价，客服会提前和您确认。如果您一次买多件，建议合并下单享受满包邮。新疆、西藏、青海等偏远地区运费稍高，具体可以咨询客服。如果您对运费有疑问，下单前可以先加入购物车，系统会自动计算运费哦。回购老客户有专属运费优惠，记得联系客服报备，让您买得更划算' AS answer, '运费,包邮,条件,合并,优惠' AS tags, '买家咨询运费及包邮条件' AS source_summary, 80 AS score
  UNION ALL SELECT 'handcraft_materials', '材料收到有色差或者质量问题怎么办？', '亲，我们承诺7天无理由退换，质量问题包退包换哦。收到货后请当面验收，如有色差、少件、损坏等问题，请在48小时内拍照联系客服，我们会第一时间处理。退换货运费由责任方承担，质量问题我们承担来回运费。如果是个人原因不喜欢，未拆封未使用可以退换，买家承担运费即可。我们的材料都有质量保障，但手作材料偶有色差属正常现象，我们会尽量减少色差，让您满意' AS answer, '售后,退换,质量,色差,保障' AS tags, '买家咨询售后退换及质量保障' AS source_summary, 86 AS score
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

-- ============ 2. 手工成品 handcraft_products (30条) ============
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.61', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'handcraft_products' AS code, '这些手工成品都是你自己做的吗？是原创设计吗？' AS question, '亲，店里的作品都是我自己手工原创设计的哦，每件都融入了独特的设计理念，不是流水线产品。从选材、打版到制作都由我亲自完成，保证每件作品的独特性和品质。部分作品有设计师认证标识，可以扫码查验。因为是纯手工制作，每件都会有细微差异，这也正是手作的温度和魅力所在。如果您有定制需求，也可以和我沟通想法，我帮您设计专属作品哦，独一无二更有心意' AS answer, '原创,手工,设计,独特,定制' AS tags, '买家咨询成品原创性及设计理念' AS source_summary, 90 AS score
  UNION ALL SELECT 'handcraft_products', '如果定制一件，大概多久能做好？', '亲，定制工期根据作品复杂程度不同哦。简单款如手链、钥匙扣3到5天，中等难度如布艺包、玩偶7到10天，复杂款如大型拼布、定制摆件可能需要2到3周。定制流程是：先沟通需求，确认设计图，支付定金，开始制作，完成拍照确认，付尾款发货。定制作品不支持退换，请确认设计图后再开始制作。如果您有加急需求可以沟通，尽量帮您安排，但为保证品质不会过度赶工哦' AS answer, '定制,工期,流程,加急,品质' AS tags, '买家咨询定制周期及流程' AS source_summary, 88 AS score
  UNION ALL SELECT 'handcraft_products', '我想送人，有礼盒包装吗？', '亲，有的哦！我们提供精美的礼盒包装服务，包含：牛皮纸礼盒、丝带蝴蝶结、贺卡、填充丝带纸，包装精美有质感，送人很有面子。礼盒包装费5元，满200元免费升级。贺卡可以代写祝福语，您把想说的话发给我即可。如果是生日礼物、纪念日礼物，还可以加配小灯串或干花装饰，氛围感拉满。直接拍下备注礼盒装加祝福语内容就行，我会精心为您准备哦' AS answer, '包装,礼盒,礼物,贺卡,赠送' AS tags, '买家咨询礼物包装及贺卡服务' AS source_summary, 89 AS score
  UNION ALL SELECT 'handcraft_products', '包装里包含贺卡吗？能代写吗？', '亲，贺卡是包含在礼盒包装里的哦，不需要额外付费。我们提供3种贺卡款式可选：简约牛皮纸款、温馨插画风、复古烫金款，您可以备注喜好。代写祝福语是免费的，您把想写的内容发给我，我会用漂亮的手写体誊写。如果不知道写什么，我也可以根据对象和场合帮您拟一段温馨的祝福语。贺卡和礼盒搭配起来特别有心意，收礼人打开的瞬间一定会被暖到哦' AS answer, '贺卡,代写,祝福,礼盒,心意' AS tags, '买家咨询贺卡及代写服务' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_products', '母亲节送什么手工礼物好？', '亲，母亲节推荐几款特别有意义的礼物哦。第一款是手工钩织康乃馨胸针，永不凋谢寓意母爱永恒，29元精致小巧。第二款是定制手写书信布艺相框，可以印上您和妈妈的合照，配手写祝福，68元很有纪念意义。第三款是手工编织披肩，柔软保暖，妈妈日常都能用，158元实用又贴心。所有母亲节礼品都配精美礼盒和贺卡，提前7天下单还能享受早鸟价9折哦，送妈妈的不二之选' AS answer, '母亲节,礼物,推荐,定制,礼盒' AS tags, '买家咨询母亲节手工礼物推荐' AS source_summary, 91 AS score
  UNION ALL SELECT 'handcraft_products', '可以在作品上刻字吗？能刻什么内容？', '亲，部分材质的作品支持刻字定制哦。木质摆件、皮质钱包、陶瓷杯子、金属书签都可以激光刻字，刻字内容可以是名字、日期、短句祝福、简笔画等。中文最多刻20字，英文最多40字符，刻字费10到20元根据内容复杂度。刻字效果清晰永久，不掉色不磨损。下单时备注刻字内容和字体偏好就行。如果是特殊图案或logo，可以先发图给我评估可行性哦' AS answer, '刻字,定制,木质,陶瓷,个性化' AS tags, '买家咨询刻字定制服务' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_products', '这个作品有几种颜色可选？能定制颜色吗？', '亲，这款作品目前有5种颜色：奶白、雾霾蓝、豆沙粉、燕麦色、炭灰，都是百搭高级色系。定制颜色也可以哦，您发色卡或图片给我，我尽量调出相近颜色。定制颜色需要加10到20元调色费，工期多2到3天。如果是织品类，毛线颜色可以参考我们店铺的毛线色卡，有40多种可选。建议选颜色时考虑使用场景和搭配，不确定的话我可以给您推荐几款适合的，拍下后发实物图确认哦' AS answer, '颜色,定制,选择,色卡,搭配' AS tags, '买家咨询颜色选择及定制' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_products', '这个作品能改尺寸吗？我想要大一号的。', '亲，大部分作品都可以调整尺寸哦。织品类如围巾、披肩、玩偶可以加减针数调整，加尺寸需要补材料费差价，工期多3到5天。布艺品如包包、收纳可以调整版型，但比例会有变化，建议先沟通确认效果。硬质材料如木质、陶瓷一旦成型无法改尺寸，需要重新制作，相当于定制新品。改尺寸前建议先和我沟通您的具体需求，我评估可行性和费用，确认后再开始制作，避免做出来不满意哦' AS answer, '尺寸,定制,调整,织品,布艺' AS tags, '买家咨询尺寸定制可行性' AS source_summary, 83 AS score
  UNION ALL SELECT 'handcraft_products', '我很急，能三天内做好吗？加急费多少？', '亲，简单款如手链、钥匙扣、小摆件可以3天内加急完成，加急费10到20元。复杂款如毛衣、大型摆件、定制相框最低也需要5到7天，加急可能影响品质，建议留足时间。加急订单会优先排单，但不接受过于赶工导致品质下降的要求。如果真的很急，建议选择现货款加定制刻字方案，1到2天就能发货。下单前先和我沟通您的截止日期，我评估后告诉您能否加急，避免耽误您的重要场合哦' AS answer, '加急,工期,费用,现货,优先' AS tags, '买家咨询加急制作及费用' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_products', '手工成品收到不满意能退吗？', '亲，现货作品支持7天无理由退换，不影响二次销售的情况下都可以退。定制作品因为是按您需求专属制作，不支持无理由退换，但如果是品质问题我们包退包换。收到货后请当面验货，如有运输损坏、做工问题，48小时内拍照联系客服处理。退货时请保留原包装和配件，确保完整。我们的作品都有品质保障，制作过程会拍照发您确认，确保做出来的效果符合预期，让您买得放心哦' AS answer, '售后,退换,定制,保障,验货' AS tags, '买家咨询成品退换政策' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_products', '买成品送工具吗？后续自己能修吗？', '亲，成品本身不附赠工具哦，但如果是小修小补，我可以免费帮您调整。比如织品起球了可以寄回来打理，串珠松了可以重新穿线，这些小问题都免费服务。如果您想自己动手，我可以推荐基础工具套装，59元12件套够用了。也可以买材料包自己做一个，更有成就感。我们的作品做工扎实，正常使用不易损坏，但万一有问题随时联系我，售后有保障，不会让您头疼哦' AS answer, '工具,维修,售后,材料包,保养' AS tags, '买家咨询工具及维修服务' AS source_summary, 82 AS score
  UNION ALL SELECT 'handcraft_products', '这个手工摆件怎么保养？容易脏吗？', '亲，不同材质保养方法不同哦。布艺织品：定期吸尘，局部污渍用中性洗涤剂轻擦，避免暴晒。陶瓷摆件：干布擦拭，避免磕碰，不要用硬物刮擦。木质作品：避免潮湿和暴晒，定期涂木蜡油保养。串珠饰品：避免接触化妆品香水，用后擦净装密封袋。超轻粘土作品：避免潮湿，可用软毛刷清洁，不要水洗。正确保养能让作品陪伴您很久哦，有任何保养问题随时问我' AS answer, '保养,材质,清洁,维护,耐用' AS tags, '买家咨询作品保养方法' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_products', '这个摆件多大？放书桌上合适吗？', '亲，这款摆件尺寸是15cm乘10cm乘8cm，放书桌、办公桌、玄关都很合适哦。重量约300g，底部有防滑垫，放稳不倒。我们还有大号20cm和小号10cm可选，大号适合放客厅茶几或展示柜，小号适合放床头或车饰。尺寸都是手工测量，可能有1到2cm误差。如果您有特定摆放空间，可以先量好尺寸再选，或者发照片给我帮您推荐合适的款式和大小哦' AS answer, '尺寸,摆件,书桌,规格,推荐' AS tags, '买家咨询摆件尺寸及摆放' AS source_summary, 83 AS score
  UNION ALL SELECT 'handcraft_products', '这个作品是什么材质的？环保吗？', '亲，这款作品主要材质是天然棉线加环保填充棉，都是经过检测的环保材料哦，无毒无异味，母婴级别安全。棉线采用活性染料染色，色牢度高不褪色。填充棉是PP三维卷曲纤维，蓬松回弹好不易变形。如果是混合材质作品，详情页会标注每种材质的占比和来源。我们坚持使用环保优质材料，虽然成本高一些，但做出来的作品更安全、更耐用、更有质感，让您用得放心哦' AS answer, '材质,环保,棉线,填充,安全' AS tags, '买家咨询作品材质及环保性' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_products', '这个是纯手工做的吗？工艺复杂吗？', '亲，是的，这款作品是纯手工制作哦，从选材到成品需要经过20多道工序。以这款编织玩偶为例：设计打版，选线配色，钩织主体，填充定型，缝合组装，细节装饰，质检包装，每一步都由手工完成，一个作品需要8到12小时。手工制作的温度和细节是机器无法替代的，每个针脚都带着制作者的心意。虽然产量有限，但每件都保证品质，这也是手作作品的珍贵之处哦' AS answer, '手工,工艺,制作,复杂,品质' AS tags, '买家咨询手工制作工艺' AS source_summary, 88 AS score
  UNION ALL SELECT 'handcraft_products', '这个适合送闺蜜吗？有什么推荐？', '亲，送闺蜜推荐几款特别有心意的作品哦。第一款是手工编织手绳，可以定制两人的名字缩写，19元起寓意友谊长存。第二款是布艺收纳袋套装，实用又好看，闺蜜日常用着就会想起您，59元。第三款是定制插画相框，把你们的合照做成手绘风，68元超有意义。如果是生日礼物，可以加配贺卡和礼盒，写上专属祝福。送闺蜜不在于贵，而在于心意，手工礼物最能体现您的用心哦' AS answer, '闺蜜,礼物,推荐,定制,心意' AS tags, '买家咨询闺蜜礼物推荐' AS source_summary, 90 AS score
  UNION ALL SELECT 'handcraft_products', '成品怎么包装？运输会坏吗？', '亲，我们包装很用心哦，确保运输安全。布艺织品：真空袋加防水袋加牛皮纸盒，防潮防挤压。陶瓷玻璃：气泡膜多层包裹加泡沫填充加加厚纸箱，防震防摔。木质摆件：珍珠棉包裹加硬纸盒，防刮防磕。每件作品发货前都会拍照确认，包装过程也会拍照留档。万一运输损坏，我们承担损失补发或退款，您不用担心。收到后如有包装破损请先拒收或拍照，联系客服处理哦' AS answer, '包装,运输,安全,防震,损坏' AS tags, '买家咨询包装及运输安全' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_products', '这个作品有现货吗？还是下单才做？', '亲，店内作品分两种：现货款和定制款。现货款有成品库存，下单24小时内发货，页面会标注现货。定制款需要下单后制作，工期根据复杂度3到15天不等。热门款一般保持5到10件现货，售完后转为预售。如果您急用，建议选现货款；如果想要独一无二的设计，选定制款更合适。下单前可以咨询客服确认库存和工期，避免耽误您的安排哦。我们也会尽量备足现货，让大家买到即发' AS answer, '现货,定制,库存,工期,预售' AS tags, '买家咨询现货及定制区别' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_products', '为什么手工成品比机器做的贵？', '亲，手工成品的价格包含了几部分：优质材料成本加人工制作成本加设计创意价值加品质保障。机器量产是规模化降低成本，但缺乏独特性和温度。手工作品每件都是独一无二的，制作者投入了大量时间和心血，一个作品可能需要几小时甚至几天完成。而且手工制作能控制每个细节，品质更精细。您买的不仅是一件作品，更是设计师的创意和匠人的心意。如果追求性价比，也有简单款19.9元起可选哦' AS answer, '价格,手工,价值,创意,性价比' AS tags, '买家咨询手工成品定价原因' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_products', '我们公司想团购一批手工礼物，有优惠吗？', '亲，团购当然有优惠哦！10件以上享9折，30件以上享8折，50件以上享7折，100件以上可以谈专属合作价。团购可以统一设计风格但每件略有差异，也可以做企业定制款，加印公司logo或活动主题。工期根据数量协商，一般10件7到10天，50件可能需要2到3周。包装可以做企业礼盒，附赠定制贺卡。如果您有团购需求，可以联系客服详细沟通需求，我们提供一对一团购方案定制服务哦' AS answer, '团购,优惠,企业,定制,批量' AS tags, '买家咨询团购及企业定制优惠' AS source_summary, 88 AS score
  UNION ALL SELECT 'handcraft_products', '定制作品如果做出来我不喜欢能退吗？', '亲，定制作品的退款政策比较特殊哦。制作过程中我会拍照发您确认每个阶段的效果，所以基本不会出现做出来不满意的情况。如果制作中您想修改设计，可以在确认阶段提出，我帮您调整。但一旦确认开始最终制作，就不能退款了，因为材料已经消耗、时间已经投入。如果是品质问题，我们包退包换。建议定制前充分沟通需求，确认设计图后再开始制作，避免双方损失哦' AS answer, '退款,定制,确认,品质,沟通' AS tags, '买家咨询定制作品退款政策' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_products', '发什么快递？能指定顺丰吗？', '亲，默认发中通或圆通，包邮款不指定快递哦。如果您想发顺丰，可以补差价升级，一般加10到15元根据地区。下单时备注发顺丰并联系客服补差价即可。偏远地区（新疆、西藏、青海等）默认发EMS或邮政，运费稍高，具体咨询客服。大件或重物可能走德邦物流。发货后会有单号，您可以实时查询物流。急用的话建议选顺丰，速度快服务好，确保按时收到哦' AS answer, '快递,顺丰,发货,物流,加急' AS tags, '买家咨询快递及发货方式' AS source_summary, 82 AS score
  UNION ALL SELECT 'handcraft_products', '这个作品有什么寓意吗？送人合适吗？', '亲，每件作品都有独特寓意哦。比如这款手工编织手绳，绳谐音神，寓意守护平安；不同颜色也有含义：红色旺运、粉色招桃花、蓝色保平安。编织玩偶代表陪伴和温暖，送孩子或恋人很有心意。布艺收纳袋寓意袋袋平安，乔迁送很合适。陶瓷摆件象征圆满，新婚送礼佳选。如果您有特定送礼场景，可以告诉我对象和场合，我推荐最合适的作品，还能附赠寓意卡片哦' AS answer, '寓意,送礼,手绳,编织,推荐' AS tags, '买家咨询作品寓意及送礼建议' AS source_summary, 89 AS score
  UNION ALL SELECT 'handcraft_products', '我是回购客户，有优惠吗？', '亲，当然有老客户专属优惠哦！第一次购买后会自动成为会员，享9.5折优惠。累计消费满500元升级银卡会员享9折，满2000元升级金卡会员享8.5折。会员还有生日礼包、新品优先购、专属优惠券等福利。回购时联系客服报手机号即可查询会员等级并应用优惠。我们还有会员群，定期有抽奖、秒杀、教程分享等活动，老客户福利多多。您的每一次支持我们都记在心里，会用更好的服务回馈您' AS answer, '老客户,会员,优惠,回购,福利' AS tags, '买家咨询老客户优惠及会员制度' AS source_summary, 88 AS score
  UNION ALL SELECT 'handcraft_products', '这个作品多重？邮寄方便吗？', '亲，这款作品约200g，加上包装约350g，邮寄很方便哦。小件作品如手链、胸针、钥匙扣50g以内，快递费便宜。中型作品如摆件、玩偶200到500g，正常快递费。大型作品如拼布画、装饰画可能1到2kg，运费稍高。我们包邮条件下不限重量，但偏远地区可能需要补差价。如果您要寄国外或港澳台，建议咨询客服确认物流方式和费用。总之重量都不算大，邮寄不会成为负担哦' AS answer, '重量,邮寄,快递,费用,包装' AS tags, '买家咨询作品重量及邮寄' AS source_summary, 81 AS score
  UNION ALL SELECT 'handcraft_products', '这个作品适合放哪里？怎么搭配？', '亲，这款作品百搭性强，多种场景都适合哦。放书桌、办公桌增添文艺氛围；放玄关、客厅茶几提升空间格调；放床头、梳妆台营造温馨感；放车里做装饰也很合适。搭配建议：和绿植、书籍、相框组合摆放更有层次感；同色系搭配显高级，撞色搭配更有个性。如果是织品类，可以搭在沙发、椅背上做点缀。不确定怎么搭配的话，可以发您家里的空间照片，我帮您推荐合适的款式和摆放方式哦' AS answer, '场景,搭配,摆放,装饰,文艺' AS tags, '买家咨询作品使用场景及搭配' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_products', '预算100以内送女朋友，有什么推荐？', '亲，100以内送女朋友有几款特别合适的哦。第一款是手工编织情侣手绳，可以定制两人名字，39元寓意甜蜜。第二款是布艺化妆包，柔软实用，女朋友每天用都能想起您，59元。第三款是超轻粘土定制人偶，根据你们的合照制作，88元独一无二。第四款是手工干花相框，放你们的合照，68元浪漫温馨。所有礼品都配精美礼盒和贺卡，代写甜蜜祝福。预算内也能送出心意，女朋友一定会感动的哦' AS answer, '推荐,女友,预算,礼物,定制' AS tags, '买家咨询百元内女友礼物推荐' AS source_summary, 91 AS score
  UNION ALL SELECT 'handcraft_products', '现在下单大概什么时候能收到？', '亲，工期分两种情况哦。现货款下单后24小时内发货，江浙沪1到2天到，其他地区2到4天，一般下单后3到5天能收到。定制款需要制作时间，简单款3到5天加物流3到5天等于7到10天收到；复杂款7到15天加物流3到5天等于10到20天收到。如果您有特定时间需求（生日、纪念日等），建议提前10到15天下单，留足时间。急用可以选现货款或咨询加急服务。下单时备注您的截止时间，我会优先安排哦' AS answer, '工期,发货,到货,时间,加急' AS tags, '买家咨询下单到收货时间' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_products', '这个作品背后有什么故事吗？', '亲，每件作品都有它的故事哦。比如这款编织小兔，灵感来自我童年养的兔子团团，希望传递陪伴和治愈的感觉。这款拼布包的花色搭配，是源于一次旅行看到的晚霞色彩。这款陶瓷杯的纹路，是模仿家乡老屋的瓦片纹理。手作不仅是技术，更是情感的表达。每件作品都带着制作者的故事和温度，这也是手工和机器最大的区别。如果您对某件作品感兴趣，我可以和您分享它背后的创作故事哦' AS answer, '故事,创作,灵感,手工,情感' AS tags, '买家咨询作品创作故事' AS source_summary, 90 AS score
  UNION ALL SELECT 'handcraft_products', '我们工作室想批量拿货，能长期合作吗？', '亲，非常欢迎工作室长期合作哦！我们可以提供稳定供货和专属批发价。合作方式灵活：第一种选店内在售款批量拿货，10件起9折，50件起8折。第二种提供设计图我帮您代工制作，按件计费，量大优惠。第三种您提供品牌和需求，我帮您开发独家产品线，长期供货。合作前可以先试样，满意后签合作协议，确保品质和交期。我们还提供产品拍照、详情页素材等支持，帮您降低运营成本。有意的话可以详细沟通需求哦' AS answer, '批量,合作,工作室,批发,定制' AS tags, '买家咨询批量合作及供货方案' AS source_summary, 89 AS score
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

-- ============ 3. 编织工艺 handcraft_knitting (30条) ============
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.61', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'handcraft_knitting' AS code, '这个毛衣有什么尺寸？我穿M码合适吗？' AS question, '亲，这款毛衣有S、M、L、XL四个尺码哦。M码胸围100cm，衣长62cm，适合120到130斤的亲穿着。因为是手工编织有弹性，实际胸围可以拉伸5到8cm。建议您量一下自己常穿毛衣的平铺胸围对比选择，如果喜欢宽松可以选大一码。如果您身材特殊或者想要更合身，也可以定制尺寸，加20元工期多5天。拍下时备注身高体重，我可以帮您推荐最合适的尺码哦' AS answer, '毛衣,尺寸,尺码,定制,推荐' AS tags, '买家咨询毛衣尺寸选择' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_knitting', '手织毛衣会起球吗？怎么打理？', '亲，这款毛衣采用优质牛奶棉线，正常穿着不易起球哦。但任何毛线在摩擦多的部位（腋下、袖口）都可能有轻微起球，这是正常现象。打理建议：手洗水温30度以内，用中性洗涤剂轻柔按压，不要用力拧绞；平铺晾干避免悬挂变形；起球时用毛球修剪器轻轻处理，不要手撕。正确打理能让毛衣穿2到3年依然好看。我们附赠一次免费打理服务，穿久了可以寄回来帮您整理哦' AS answer, '毛衣,起球,打理,洗涤,保养' AS tags, '买家咨询毛衣起球及打理方法' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_knitting', '这个毛衣能机洗吗？会缩水吗？', '亲，手织毛衣建议手洗哦，机洗容易导致变形和缩水。如果实在要机洗，请套洗衣袋、选轻柔模式、冷水洗涤。手洗方法：30度冷水加中性洗涤剂，浸泡5分钟，轻柔按压，不要搓揉；漂洗干净后用毛巾吸水，平铺晾干。千万不要悬挂晾干，水分重力会拉长变形。也不要暴晒或烘干，会导致缩水。正确洗涤能让毛衣保持原本形态，穿很久依然舒适。附赠洗衣说明卡，照着做就行哦' AS answer, '毛衣,洗涤,机洗,缩水,保养' AS tags, '买家咨询毛衣洗涤及缩水问题' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_knitting', '围巾有多长？能绕几圈？', '亲，这款围巾长度180cm，宽度25cm，能绕脖子两圈还有余量下垂，效果优雅又保暖哦。如果您喜欢短款利落，也有150cm可选；喜欢长款慵懒风，有200cm加长款。围巾长度选择建议：150cm适合单圈或半圈围法，利落干练；180cm最百搭，两圈刚好；200cm适合高个子或者喜欢层叠穿搭的。男士推荐180cm，女士推荐150到180cm。不确定的话选180cm准没错，男女都适合哦' AS answer, '围巾,长度,尺寸,选择,搭配' AS tags, '买家咨询围巾长度及围法' AS source_summary, 83 AS score
  UNION ALL SELECT 'handcraft_knitting', '围巾是什么材质的？扎不扎人？', '亲，这款围巾是100%牛奶棉材质哦，手感柔软顺滑，完全不扎人，亲肤级别。相比羊毛围巾，牛奶棉更柔软、不易过敏、好打理；相比腈纶围巾，牛奶棉更保暖、透气性好、不起静电。围巾厚度适中，春秋单层围足够，冬天可以绕两圈或搭配大衣。重量约200g，围一整天不累。颜色有12种可选，都是百搭色系。如果您皮肤敏感，这款特别适合，很多客户反馈比商场买的还舒服哦' AS answer, '围巾,材质,牛奶棉,柔软,亲肤' AS tags, '买家咨询围巾材质及亲肤性' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_knitting', '围巾会掉毛吗？黑色衣服上会沾吗？', '亲，这款围巾经过锁绒工艺处理，正常使用是不掉毛的哦。新围巾第一次使用可能有少许浮毛，轻拍或用粘毛器处理即可，洗过一次后就不会再掉。相比羊毛围巾，牛奶棉的掉毛问题几乎可以忽略，穿黑色衣服也不用担心沾毛。建议首次使用前先用冷水轻洗一次，晾干后再戴，既能去除浮毛，也能让围巾更柔软。平时存放建议密封袋装好，避免和粗糙衣物摩擦。有任何问题随时问我哦' AS answer, '围巾,掉毛,锁绒,洗涤,存放' AS tags, '买家咨询围巾掉毛问题' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_knitting', '玩偶里面填充的是什么？安全吗？', '亲，玩偶填充物是优质PP棉（聚酯纤维三维卷曲棉），经过检测认证，无毒无异味，母婴级别安全哦。PP棉蓬松度高、回弹好、不易结块，填充饱满不易变形。相比普通棉花，PP棉不会发霉生虫，长期使用依然蓬松。玩偶外层是牛奶棉钩织，柔软亲肤。整件作品适合3岁以上儿童玩耍，也可以做宝宝安抚玩偶。如果是给婴儿使用，建议选择无小配件款式，避免误吞。我们也有专门的儿童安全系列哦' AS answer, '玩偶,填充,PP棉,安全,儿童' AS tags, '买家咨询玩偶填充物安全性' AS source_summary, 88 AS score
  UNION ALL SELECT 'handcraft_knitting', '玩偶脏了能洗吗？怎么洗不变形？', '亲，玩偶是可以洗的哦，建议手洗不要机洗。清洗方法：30度温水加中性洗涤剂，轻柔按压，不要拧绞；漂洗干净后用毛巾包裹吸水；整形后平铺晾干，避免暴晒和烘干。顽固污渍可以用软毛刷蘸洗涤剂轻刷。洗后稍微拍打让填充物恢复蓬松。如果是局部脏污，可以用湿巾擦拭，不用整洗。平时存放避免潮湿，可以放一包干燥剂。正确清洗能让玩偶陪伴孩子很久，依然干净可爱哦' AS answer, '玩偶,清洗,洗涤,保养,变形' AS tags, '买家咨询玩偶清洗方法' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_knitting', '抱枕含内胆吗？还是只有枕套？', '亲，这款抱枕是枕套加内胆全套哦，收到就能直接用。内胆是PP棉填充，饱满有弹性，靠背舒适。枕套是手工编织，可拆卸清洗。也有只卖枕套的选项，价格便宜40元，您可以选自己喜欢的方式。内胆尺寸45cm乘45cm标准款，适配大部分沙发。如果您需要其他尺寸，可以定制，加15元工期3天。抱枕套颜色有8种可选，混搭多个更有层次感。一套在手，沙发立刻温馨起来哦' AS answer, '抱枕,内胆,枕套,尺寸,定制' AS tags, '买家咨询抱枕内胆配置' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_knitting', '我想学钩针，有教程推荐吗？', '亲，欢迎入坑钩针哦！新手推荐学习路线：第一步先掌握基础针法（锁针、短针、长针），可以看B站免费教程。第二步从简单作品练手，比如杯垫、方形织片，熟悉手感。第三步进阶做小玩偶、围巾，练习立体塑形。第四步挑战复杂作品如毛衣、拼花。我们店有新手材料包，包含钩针、毛线、图文教程、视频教程，19.9元起，一站式入门。购买后可以加入学习群，有老师答疑和作品交流。钩针入门容易，做出成品超有成就感，赶紧开始吧' AS answer, '钩针,教程,新手,入门,材料包' AS tags, '买家咨询钩针学习路径' AS source_summary, 91 AS score
  UNION ALL SELECT 'handcraft_knitting', '这个玩偶能定制颜色吗？我想要粉色。', '亲，可以定制颜色哦！我们有40多种毛线颜色可选，粉色系就有樱花粉、裸粉、茱萸粉、藕粉等多种选择。定制颜色不加价，工期多2到3天。下单时备注您想要的颜色，或者参考店铺色卡选色。如果不确定选哪种粉，可以告诉我您的使用场景，我推荐最合适的。定制款还可以加绣名字或日期，独一无二更有意义。定制前我会发确认图，您满意后才开始制作，确保做出来符合预期哦' AS answer, '定制,颜色,粉色,玩偶,绣字' AS tags, '买家咨询玩偶定制颜色' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_knitting', '手织毛衣会不会透风？密度怎么样？', '亲，这款毛衣采用细针密织工艺，密度高不透风哦。用的是3.5mm钩针，针脚紧密均匀，保暖性很好。相比粗针宽松织法，密织更挡风、更保暖，但弹性和透气性稍弱。如果您在北方室外多，推荐密织款；如果南方室内为主，宽松款更舒适。我们也有不同密度的款式可选，详情页会标注针法和适合季节。如果怕冷可以选加厚款，多一层内衬，零下温度也能hold住哦' AS answer, '毛衣,密度,保暖,透风,工艺' AS tags, '买家咨询毛衣编织密度及保暖' AS source_summary, 83 AS score
  UNION ALL SELECT 'handcraft_knitting', '这个玩偶能给婴儿用吗？安全吗？', '亲，给婴儿使用建议选择专门的婴儿系列哦。普通款虽然材料也是环保无毒的，但可能有眼睛、鼻子等小配件，婴儿有误吞风险。婴儿系列特点：第一全部一体成型，无任何可拆卸小配件。第二使用A类婴儿级棉线和填充棉，通过婴幼儿安全检测。第三眼睛鼻子用刺绣工艺，不会脱落。第四尺寸适合婴儿抓握，约15到20cm。第五可水洗消毒，方便清洁。如果您需要婴儿款，可以咨询客服推荐，安全第一哦' AS answer, '婴儿,安全,玩偶,无配件,可洗' AS tags, '买家咨询玩偶婴儿安全性' AS source_summary, 90 AS score
  UNION ALL SELECT 'handcraft_knitting', '送人有礼盒装吗？包装怎么样？', '亲，有的哦！我们提供精美礼盒包装，包含：加厚牛皮纸礼盒加丝带蝴蝶结加贺卡加雪梨纸填充，包装精致有质感。礼盒装加5元，满200元免费升级。贺卡可以代写祝福语，您发内容我帮您誊写。如果是生日礼物，可以加配小灯串装饰；如果是婚礼礼物，可以选红色系礼盒。包装过程会拍照发您确认，确保满意再发货。送人特别有面子，收礼人打开的瞬间一定会被暖到哦' AS answer, '礼盒,包装,送人,贺卡,礼物' AS tags, '买家咨询礼盒包装服务' AS source_summary, 88 AS score
  UNION ALL SELECT 'handcraft_knitting', '这个毛衣会掉色吗？第一次洗注意什么？', '亲，这款毛衣采用活性染料染色，色牢度高，正常洗涤不掉色哦。第一次洗建议：冷水单独洗，加少许盐或白醋固色。不要用漂白剂或含酶洗衣液。不要长时间浸泡，5分钟即可。轻柔按压，不要搓揉。平铺晾干，避免暴晒。深色毛衣前两次洗可能有轻微浮色，这是正常现象，洗几次后就完全稳定了。如果您担心掉色，可以选择浅色系，掉色风险更低。有任何洗涤问题随时问我哦' AS answer, '毛衣,掉色,固色,洗涤,保养' AS tags, '买家咨询毛衣掉色及首次洗涤' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_knitting', '围巾厚度怎么样？冬天够暖吗？', '亲，这款围巾是中厚款，用双股牛奶棉线钩织，厚度约5mm，冬天佩戴足够保暖哦。春秋可以单层围，冬天绕两圈或搭配大衣都很暖和。如果您在北方极寒地区，推荐加厚款，用三股线钩织，厚度8mm，零下20度也能扛。加厚款加15元，工期多2天。南方的话标准款就够用了。围巾保暖性除了厚度，还看材质，牛奶棉保暖性优于腈纶，接近羊毛但更柔软。选对厚度，冬天脖子暖乎乎的哦' AS answer, '围巾,厚度,保暖,冬天,加厚' AS tags, '买家咨询围巾厚度及保暖性' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_knitting', '玩偶有多大？适合多大孩子玩？', '亲，玩偶有3种尺寸可选哦。小号15cm，适合0到3岁宝宝抓握，小巧便携。中号25cm最热门，适合3到8岁儿童，大小适中好抱。大号35cm，适合8岁以上或者做装饰摆件，抱枕级别。不同款式尺寸略有差异，详情页有标注。建议根据孩子年龄和用途选择：婴儿选小号无配件款，幼儿选中小号，大孩子选大号更有陪伴感。也可以根据孩子喜好定制造型，做出来独一无二，孩子一定超喜欢哦' AS answer, '玩偶,尺寸,儿童,选择,定制' AS tags, '买家咨询玩偶尺寸及适龄' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_knitting', '抱枕套是什么材质的？透气吗？', '亲，抱枕套是100%牛奶棉手工钩织哦，透气性很好。相比机织布艺抱枕套，钩织款更有立体纹理感，透气不闷，四季都适合使用。牛奶棉柔软亲肤，靠上去脸不痒不过敏。颜色有8种可选，都是莫兰迪色系，百搭沙发和卧室。可拆洗设计，拉链开合方便清洗。建议手洗冷水，平铺晾干，保持形状。一套抱枕能让沙发瞬间温馨，多个混搭更有层次感，是提升家居氛围的小神器哦' AS answer, '抱枕,材质,透气,牛奶棉,可洗' AS tags, '买家咨询抱枕套材质及透气性' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_knitting', '一件毛衣要织多久？为什么工期长？', '亲，一件成人毛衣纯手工编织需要40到60小时哦，分几天完成，所以工期7到15天。编织流程：选线配色，画图解，起针编织主体，袖子和领口，缝合定型，质检包装。每一步都需要精细操作，不能赶工。相比机器编织几分钟一件，手织毛衣的独特性和品质是机器无法替代的：针脚更有温度、可以定制花型、版型更合身。如果您急用，有部分现货款可以直接发，或者选简单款工期更短。好东西值得等待哦' AS answer, '毛衣,工期,编织,手工,时间' AS tags, '买家咨询毛衣编织工期原因' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_knitting', '毛衣弹性怎么样？胖人能穿吗？', '亲，手织毛衣弹性很好哦，因为钩织结构本身有伸缩性，正常可以拉伸5到8cm。如果您偏胖，建议选大一码或者定制加大款。我们最大做到4XL，胸围130cm，适合180斤以内穿着。如果更大可以定制，加30元工期多5天。毛衣版型建议选宽松款，比修身款更包容不同身材。如果您不确定尺码，可以告诉我身高体重，我帮您推荐最合适的。手织毛衣的好处就是可以量身定制，做出来合身又舒适哦' AS answer, '毛衣,弹性,尺码,加大,定制' AS tags, '买家咨询毛衣弹性及尺码选择' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_knitting', '围巾送男朋友合适吗？有男士款吗？', '亲，送围巾特别合适哦，寓意温暖你，是送男友的经典礼物。我们有专门的男士款，颜色低调（黑、灰、深蓝、咖色），款式简约大方，长度180cm适合男士。还可以定制绣字，绣上男友名字缩写或纪念日，独一无二。男士款推荐深色系，百搭各种外套。包装选礼盒装，配贺卡代写甜蜜祝福，送出去特别有心意。男朋友收到一定会感受到您的用心。现在下单，还送精美礼品袋哦' AS answer, '围巾,男友,男士,送礼,定制' AS tags, '买家咨询围巾送男友及男士款' AS source_summary, 89 AS score
  UNION ALL SELECT 'handcraft_knitting', '玩偶有哪些造型？能定制形象吗？', '亲，玩偶有几十种造型哦，热门的有：小熊、兔子、猫咪、小狗、熊猫、长颈鹿等动物系列；卡通人物系列；节日主题系列（圣诞老人、复活节兔等）。也可以根据您的照片定制形象，比如照着您的宠物做一只毛绒版，或者照着家人做Q版人偶。定制形象费用根据复杂度50到200元，工期7到10天。定制前可以先发照片我评估可行性和报价。独一无二的定制玩偶，无论是送人还是自己收藏都特别有意义哦' AS answer, '玩偶,造型,定制,形象,宠物' AS tags, '买家咨询玩偶造型及形象定制' AS source_summary, 90 AS score
  UNION ALL SELECT 'handcraft_knitting', '抱枕有哪些颜色？怎么搭配沙发？', '亲，抱枕有8种颜色：奶白、燕麦、雾霾蓝、豆沙粉、浅灰、深灰、咖色、墨绿，都是莫兰迪色系，百搭高级。搭配建议：灰色系沙发选奶白、燕麦提亮。米色沙发选雾霾蓝、墨绿撞色。深色沙发选奶白、豆沙粉柔化。彩色沙发选中性色平衡。建议买2到4个混搭，同色系深浅组合或者撞色搭配都好看。不确定怎么选可以发沙发照片给我，帮您推荐最合适的颜色组合哦' AS answer, '抱枕,颜色,搭配,沙发,莫兰迪' AS tags, '买家咨询抱枕颜色及沙发搭配' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_knitting', '毛衣有什么花型？能定制图案吗？', '亲，毛衣有多种花型可选：平针、麻花、阿兰花、菱形格、绞花等经典花型。每款都有实拍图展示效果。也可以定制图案，比如名字、字母、简单图形，定制费20到50元根据复杂度。复杂图案如人像、风景不建议手织，效果可能不理想。定制花型工期多5到7天。新手推荐平针或简单麻花，经典不易出错。如果您有特定花型需求，可以先发参考图给我评估可行性，再做决定哦' AS answer, '毛衣,花型,图案,定制,麻花' AS tags, '买家咨询毛衣花型及图案定制' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_knitting', '围巾怎么包装？送人有礼盒吗？', '亲，围巾包装很精致哦！默认包装：雪梨纸包裹加牛皮纸盒加丝带，简约有质感。礼盒装升级版：加厚礼盒加蝴蝶结加贺卡加礼品袋，5元升级，满200免费。贺卡可代写祝福语。如果是送男友，推荐简约黑色礼盒；送女友选粉色或红色礼盒更有氛围。包装时围巾会叠成美观的形状，打开瞬间有惊喜感。也可以加配小卡片写赠送方信息，特别适合节日礼物。送人特别有面子，赶紧看看吧' AS answer, '围巾,包装,礼盒,送礼,贺卡' AS tags, '买家咨询围巾包装及送礼' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_knitting', '玩偶能绣名字吗？绣多大？', '亲，可以绣名字哦！用同色或撞色线在玩偶底部或背面绣字，不影响整体美观。绣字内容可以是名字、日期、短句祝福，中文最多8字，英文最多15字符。绣字费10元，工期多1天。绣字效果精致永久，不掉色不脱落。如果是送孩子，绣上名字更有归属感；送恋人，绣上纪念日更有意义。下单时备注绣字内容和位置偏好即可。也可以先发效果图给您确认，满意后再制作哦' AS answer, '玩偶,绣字,名字,定制,礼物' AS tags, '买家咨询玩偶绣字定制' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_knitting', '抱枕能定制图案吗？我想做个照片抱枕。', '亲，抱枕可以定制简单图案哦，比如名字、字母、简单图形，用钩织或刺绣方式呈现，费用20到50元。但复杂图案如照片，钩织无法精准还原，建议选以下方案：第一种简化照片为像素风图案，我可以帮您设计。第二种选照片印在布上，再做抱枕套拼接，半手工半印刷。第三种选简单图形如心形、星星等，更有手作感。定制前可以先发照片或图案给我评估可行性和报价。手作定制的魅力在于独一无二，简单图案反而更有味道哦' AS answer, '抱枕,定制,图案,照片,设计' AS tags, '买家咨询抱枕定制图案' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_knitting', '毛衣有什么领型？圆领还是高领？', '亲，毛衣有多种领型可选：圆领、V领、高领、堆堆领、开衫翻领。圆领最百搭，适合所有人；V领修饰脸型，适合圆脸；高领保暖性好，适合冬天；堆堆领慵懒时尚；开衫方便穿脱。每种领型都有实拍图展示。如果您脖子短，建议选圆领或V领；脖子长可以选高领。领型也可以定制，比如改圆领为V领，不加价工期不变。不确定选什么领型，可以告诉我您的喜好和身材特点，我帮您推荐哦' AS answer, '毛衣,领型,圆领,高领,定制' AS tags, '买家咨询毛衣领型选择' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_knitting', '围巾有哪些款式？长条还是三角形？', '亲，围巾有多种款式：第一种经典长条款180乘25cm，最百搭。第二种加长款200乘25cm，适合层叠穿搭。第三种短款利落型150乘25cm，适合商务。第四种三角披肩款，可以当围巾也可以当披肩，多功能。第五种无限围巾（圈巾），套头即戴，方便不散开。第六种带流苏款，更有手作感。不同款式搭配不同风格，长条款经典，圈巾方便，披肩优雅。您可以告诉我想搭配什么衣服、什么场合用，我推荐最合适的款式哦' AS answer, '围巾,款式,长条,披肩,选择' AS tags, '买家咨询围巾款式选择' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_knitting', '玩偶怎么包装？送孩子有礼盒吗？', '亲，玩偶包装特别用心哦！默认包装：透明OPP袋加雪梨纸加丝带，简约可爱。礼盒装：加厚纸盒加蝴蝶结加贺卡加小卡片，5元升级，满150免费。送孩子可以选彩色礼盒，加配小灯串或糖果，孩子收到更开心。贺卡可以写祝福语或孩子的名字。如果是生日礼物，可以加配生日帽或小皇冠装饰。包装过程会拍照发您确认，确保满意。收到礼物的孩子一定会爱不释手，赶紧为孩子准备一份吧' AS answer, '玩偶,包装,礼盒,送孩子,礼物' AS tags, '买家咨询玩偶包装及送礼' AS source_summary, 87 AS score
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

-- ============ 4. 陶艺作品 handcraft_ceramic (30条) ============
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.61', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'handcraft_ceramic' AS code, '这个陶瓷杯上釉了吗？会不会渗水？' AS question, '亲，这款杯子是高温烧制加全釉面处理哦，不会渗水，可以放心使用。釉面光滑细腻，不易沾染污渍，清洗方便。我们采用的是食品级安全釉料，经过1280度高温烧制，无毒无铅，符合国家日用陶瓷标准。相比无釉的素烧陶，上釉陶瓷更实用、更卫生、更耐用。如果您喜欢哑光质感，也有哑光釉款可选；喜欢光泽感，选亮光釉款。每种釉面效果都有实拍图，可以参考选择哦' AS answer, '陶瓷,上釉,渗水,安全,高温' AS tags, '买家咨询陶瓷上釉及渗水问题' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_ceramic', '这个陶瓷杯能放微波炉吗？洗碗机呢？', '亲，这款杯子可以放微波炉和洗碗机哦。高温陶瓷经过1280度烧制，耐热性能好，微波加热没问题。釉面也是耐高温的，不会释放有害物质。洗碗机清洗也可以，但建议放在上层避免磕碰。不过有金属装饰（金边、银边）的款式不建议微波，会打火花。使用注意：避免骤冷骤热，比如从冰箱取出不要立即倒开水，防止热胀冷缩开裂。正常使用的话，一个杯子可以用很多年哦' AS answer, '陶瓷,微波,洗碗机,耐热,使用' AS tags, '买家咨询陶瓷微波及洗碗机使用' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_ceramic', '这个花瓶多大？能插几支花？', '亲，这款花瓶高20cm，瓶口直径8cm，适合插5到7支玫瑰或3到5支百合。瓶身最大直径12cm，底部稳定不倒。还有小号15cm和大号25cm可选。小号适合插干花或小束鲜花，放书桌；中号最百搭，放餐桌、茶几；大号适合客厅或玄关大空间。花瓶口径设计合理，插花不需要花泥也能固定。如果您想插特定花材，可以告诉我，我推荐合适的尺寸和款式。手工陶瓷花瓶插上鲜花，家里立刻有格调哦' AS answer, '花瓶,尺寸,插花,选择,搭配' AS tags, '买家咨询花瓶尺寸及插花' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_ceramic', '这个杯子容量多少？能装多少水？', '亲，这款杯子容量300ml，正常一杯水或咖啡刚好。还有200ml小杯和400ml大杯可选。200ml适合浓缩咖啡或茶；300ml最实用，咖啡、牛奶、水都适合；400ml适合大杯拿铁或泡面。杯子尺寸：300ml款口径8cm，高9cm，握感舒适。把手设计符合人体工程学，不烫手。如果您平时喝水量大，推荐400ml；办公室用300ml最合适。也可以买不同容量组合套装，满足不同场景需求哦' AS answer, '杯子,容量,选择,尺寸,把手' AS tags, '买家咨询杯子容量及选择' AS source_summary, 83 AS score
  UNION ALL SELECT 'handcraft_ceramic', '陶瓷摆件怎么保养？容易碎吗？', '亲，陶瓷摆件保养很简单哦。日常用干布或软毛刷除尘即可，避免用水冲洗防止积水发霉。摆放时避免磕碰和跌落，陶瓷是易碎品要轻拿轻放。避免阳光直射，防止釉面褪色。如果落灰较多，可以用湿布擦拭后立即擦干。展示柜摆放最佳，既能保护又能展示。如果有小瑕疵可以用透明指甲油修补。正常保养的话，陶瓷摆件可以保存几十年甚至更久，是值得收藏的艺术品哦' AS answer, '陶瓷,保养,摆件,易碎,收藏' AS tags, '买家咨询陶瓷摆件保养方法' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_ceramic', '这个陶瓷是什么工艺烧的？温度多少？', '亲，我们采用传统手工拉坯加高温窑烧工艺哦。流程：选土，揉泥，拉坯，修坯，上釉，窑烧，每步都由匠人手工完成。烧制温度1280度高温，烧制时间约12小时，自然降温48小时。高温烧制的陶瓷密度高、吸水率低、耐用性好。相比低温陶（800到900度），高温瓷更坚硬、釉面更亮、不渗水。每件作品因手工制作，会有细微差异和窑变效果，这也是手作陶瓷的独特魅力。值得收藏和日常使用哦' AS answer, '陶瓷,工艺,烧制,高温,手工' AS tags, '买家咨询陶瓷烧制工艺' AS source_summary, 88 AS score
  UNION ALL SELECT 'handcraft_ceramic', '陶瓷杯能刻字吗？怎么收费？', '亲，陶瓷杯可以刻字哦！在烧制前于坯体上刻字，烧制后字迹永久保留，不掉色不磨损。刻字内容可以是名字、日期、短句祝福，中文最多10字，英文20字符。刻字费15到30元根据字数和复杂度。下单时备注刻字内容、字体偏好（楷体、宋体、英文体）、刻字位置。也可以加刻简单图案如心形、星星。刻字款需要重新制作，工期7到10天。送人特别有心意，独一无二的专属杯子，赶紧定制一个吧' AS answer, '陶瓷,刻字,定制,杯子,礼物' AS tags, '买家咨询陶瓷刻字定制' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_ceramic', '陶瓷怎么包装？运输会碎吗？', '亲，陶瓷包装我们特别用心，确保运输安全！包装流程：气泡膜多层包裹，珍珠棉填充，泡沫定型，加厚瓦楞纸箱，易碎标识。每件作品包装前都会检查无瑕疵，包装过程拍照留档。我们和快递公司有协议，易碎品优先处理。万一运输破损，我们免费补发，您不用担心。收到后请当面验货，如有破损请拒收或拍照联系客服，48小时内处理。我们的破损率控制在1%以下，但还是建议您当面试试哦' AS answer, '陶瓷,包装,运输,防碎,破损' AS tags, '买家咨询陶瓷包装及运输安全' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_ceramic', '陶瓷有什么颜色？釉色会一样吗？', '亲，陶瓷有10多种釉色可选：经典白、天青、粉青、霁蓝、豆绿、窑变、黑釉、结晶釉等。每款釉色都是高温窑烧自然形成，会有窑变效果，每件略有差异，独一无二。如果您对颜色要求严格，建议选纯色釉（白、蓝、绿），窑变效果较少；如果喜欢独特感，选窑变釉或结晶釉，每件都是孤品。釉色受窑温和气氛影响，无法100%复制，这也是手工陶瓷的珍贵之处。下单前可以参考实拍图，但实际收到会有小惊喜哦' AS answer, '陶瓷,颜色,釉色,窑变,选择' AS tags, '买家咨询陶瓷颜色及釉色差异' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_ceramic', '陶瓷定制多久能做好？为什么工期长？', '亲，陶瓷定制工期15到20天哦，比其他手作更长，因为工艺流程复杂。流程：选款沟通，拉坯成型（1到2天），自然晾干（3到5天），修坯刻字（1天），第一次烧制素烧（1天），上釉（1天），第二次高温烧制（2天），自然降温（2天），质检包装（1天）。每个环节都需要时间，不能赶工，否则容易开裂或失败。烧制还有一定失败率，如果出窑后有问题需要重做。好东西值得等待，收到成品时一定觉得值得哦' AS answer, '陶瓷,工期,定制,流程,烧制' AS tags, '买家咨询陶瓷定制工期原因' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_ceramic', '陶瓷釉面含铅吗？用来喝水安全吗？', '亲，我们使用的是无铅环保釉料，经过检测符合国家日用陶瓷标准，可以放心用来喝水、喝茶、喝咖啡哦。高温烧制（1280度）后釉面稳定，不会释放任何有害物质。检测报告可以在详情页查看，也可以联系客服索取。建议购买日用陶瓷时选择有检测报告的商家，避免买到劣质含铅产品。我们所有接触食物的陶瓷都使用食品级釉料，安全有保障。您和家人可以放心使用，享受每一杯水哦' AS answer, '陶瓷,含铅,安全,釉料,检测' AS tags, '买家咨询陶瓷含铅安全性' AS source_summary, 90 AS score
  UNION ALL SELECT 'handcraft_ceramic', '杯子把手牢固吗？会不会断？', '亲，杯子把手是和杯身一体拉坯成型后粘接的，经过高温烧制牢牢结合，正常使用不会断裂哦。把手设计经过人体工程学考量，握感舒适，承重足够。使用时避免磕碰和骤冷骤热，不要用力掰扯。如果把手出现松动（极少数情况），联系客服可以补发或修复。我们也有些款式是无把手双手捧杯设计，更适合喝茶品茗。如果您对把手有特殊要求，可以咨询客服推荐合适的款式。放心使用，正常可以用很多年哦' AS answer, '杯子,把手,牢固,设计,使用' AS tags, '买家咨询杯子把手牢固性' AS source_summary, 83 AS score
  UNION ALL SELECT 'handcraft_ceramic', '花瓶能装水插真花吗？会渗水吗？', '亲，这款花瓶是高温陶瓷加全釉面处理，内壁也有釉层，装水不渗漏，可以放心插真花哦。釉面光滑易清洗，换水时冲洗即可。相比素烧陶花瓶会渗水，上釉陶瓷更实用。使用建议：换水每2到3天一次，保持水质清洁。花瓶底部放小石子固定花枝。避免阳光直射延长花期。长期不用时擦干存放。我们也有些款式是干花专用（无内釉），价格更优惠，如果只插干花可以选那款。插上鲜花，家里立刻有生机哦' AS answer, '花瓶,防水,渗水,插花,清洗' AS tags, '买家咨询花瓶防水及插真花' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_ceramic', '这个摆件多大？放哪里合适？', '亲，这款摆件尺寸15乘10乘8cm，重量约400g，放书桌、玄关、茶几、展示柜都合适。还有小号10cm和大号20cm可选。小号适合放书桌、床头，点缀空间；中号最百搭，各种位置都适合；大号适合客厅、玄关等大空间，更有存在感。摆件底部有防滑垫，放稳不刮桌面。如果您有特定摆放空间，可以先量好尺寸再选，或者发照片给我帮您推荐。手工陶瓷摆件能瞬间提升空间格调，是家居点缀的好选择哦' AS answer, '摆件,尺寸,摆放,陶瓷,选择' AS tags, '买家咨询摆件尺寸及摆放' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_ceramic', '陶瓷杯重吗？拿着累不累？', '亲，这款杯子约250g，装满水约550g，正常握持不累哦。我们设计时考虑了重量和厚度的平衡，既保证耐用性又不至于太重。如果您喜欢轻薄感，有薄胎款，重量180g，但价格稍高；如果喜欢厚实感，有厚胎款，重量350g，更耐用。女士推荐标准款或薄胎款，握感轻盈；男士推荐标准或厚胎款，更有质感。把手设计也影响握感，我们的把手经过多次打版优化，握着舒适不滑。选对杯子，喝水都是享受哦' AS answer, '陶瓷,重量,杯子,握感,选择' AS tags, '买家咨询陶瓷重量及握感' AS source_summary, 83 AS score
  UNION ALL SELECT 'handcraft_ceramic', '什么是窑变？每件都不一样吗？', '亲，窑变是指陶瓷在高温烧制过程中，釉料发生意想不到的色彩变化，是自然形成的独特效果哦。窑变釉的陶瓷每件都是独一无二的，无法复制，这也是它的珍贵之处。常见的窑变有：天青窑变、星空窑变、流星釉、兔毫釉等。窑变效果受釉料配方、窑温、气氛、位置等多种因素影响，出窑前无法预知，开窑时就像拆盲盒一样惊喜。如果您喜欢独一无二的作品，窑变款是最佳选择，每件都是艺术品，值得收藏哦' AS answer, '窑变,陶瓷,独特,收藏,艺术' AS tags, '买家咨询窑变效果及独特性' AS source_summary, 89 AS score
  UNION ALL SELECT 'handcraft_ceramic', '这个是手工拉坯还是模具的？', '亲，我们的陶瓷是纯手工拉坯制作哦，不是模具量产。手工拉坯是将泥料放在转盘上，匠人用手和工具塑形，每件作品都有匠人的手温和个人风格。相比模具量产，手工拉坯的特点：每件独一无二，有细微差异。壁厚更均匀，质感更好。造型更灵动，不死板。可以根据需求微调造型。但手工拉坯产量有限，价格也相对高。如果您追求独特性和品质，手工拉坯是不二之选。每件作品都带着匠人的心意，值得珍藏哦' AS answer, '手工,拉坯,陶瓷,独特,品质' AS tags, '买家咨询手工拉坯工艺' AS source_summary, 88 AS score
  UNION ALL SELECT 'handcraft_ceramic', '能定制特定款式的陶瓷吗？我有参考图。', '亲，可以定制特定款式哦！您发参考图给我，我评估可行性和报价。定制流程：沟通需求，确认设计图。报价并支付定金。拉坯制作（7到10天）。烧制（5到7天）。拍照确认。付尾款发货。定制费用根据复杂度，简单款150到300元，复杂款300到800元。定制款不支持退换，制作过程会拍照确认每个阶段，确保符合预期。如果是复杂造型或特殊工艺，可能需要多次试样。手作定制独一无二，特别有意义哦' AS answer, '定制,陶瓷,款式,设计,流程' AS tags, '买家咨询陶瓷定制款式' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_ceramic', '这个陶瓷是哪里产的？是景德镇吗？', '亲，我们的陶瓷来自景德镇哦，这里是世界闻名的瓷都，有千年制陶历史。我们的工作室由资深匠人主理，传承景德镇传统工艺，同时融入现代设计美学。泥料选用景德镇本地高岭土，釉料是环保无铅配方。每件作品都经过严格质检，确保品质。相比工业化量产陶瓷，手工陶瓷更注重质感和独特性。我们也支持到店参观（景德镇），可以亲眼看看制作过程。买手工陶瓷不仅是买用品，更是买文化和艺术哦' AS answer, '景德镇,产地,陶瓷,工艺,文化' AS tags, '买家咨询陶瓷产地及背景' AS source_summary, 89 AS score
  UNION ALL SELECT 'handcraft_ceramic', '有杯子套装吗？买多个有优惠吗？', '亲，有的哦！我们有2件套、4件套、6件套可选，套装比单买更优惠。2件套适合情侣或夫妻，9折；4件套适合小家庭，8.5折；6件套适合大家庭或送礼，8折。套装可以选择同款同色，也可以混搭不同颜色和款式，组合更灵活。套装还配精美礼盒包装，送人特别有面子。如果您是工作室或商家团购，10套以上可以谈专属合作价。杯子套装实用又有格调，自用送礼都合适，赶紧看看吧' AS answer, '套装,杯子,优惠,礼盒,团购' AS tags, '买家咨询杯子套装及优惠' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_ceramic', '花瓶有哪些款式？什么风格？', '亲，花瓶有多种款式：第一种经典梅瓶，优雅复古。第二种现代简约直筒瓶，百搭现代家居。第三种异形艺术瓶，个性十足。第四种小口大肚瓶，适合插少许花材。第五种多口花瓶，可以同时插多种花。风格涵盖中式、日式、北欧、现代简约。每种款式都有实拍图和搭配建议。如果您家居是中式风格，推荐梅瓶或天青釉；北欧风格推荐简约直筒白釉；现代风格推荐异形或窑变款。不确定选什么，发家居照片给我，帮您推荐最合适的哦' AS answer, '花瓶,款式,风格,搭配,选择' AS tags, '买家咨询花瓶款式及风格' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_ceramic', '这个摆件有什么寓意？送人合适吗？', '亲，每件摆件都有独特寓意哦。比如这款葫芦摆件，寓意福禄，送长辈或开业送礼佳选；这款鱼形摆件寓意年年有余，新年礼物合适；这款莲花摆件象征和和美美，送新婚夫妇有意义；这款猫头鹰摆件寓意智慧，送学生或升职礼物合适。如果您有特定送礼场景，可以告诉我对象和场合，我推荐最合适的摆件，还能附赠寓意卡片。手工陶瓷摆件既有艺术价值又有美好寓意，送人特别有面子哦' AS answer, '摆件,寓意,送礼,陶瓷,推荐' AS tags, '买家咨询摆件寓意及送礼' AS source_summary, 88 AS score
  UNION ALL SELECT 'handcraft_ceramic', '陶瓷送长辈什么好？预算200左右。', '亲，200左右送长辈推荐几款特别合适的哦。第一款是茶杯套装（一壶两杯），天青釉配色，长辈喝茶实用，188元。第二款是陶瓷花瓶加干花套装，家居装饰有格调，168元。第三款是福禄葫芦摆件，寓意吉祥，198元送长辈有心意。第四款是陶瓷茶叶罐，存放好茶保持新鲜，178元。所有礼品都配精美礼盒和贺卡，代写祝福语。送长辈讲究实用和寓意，陶瓷礼物既有品味又有面子，长辈一定喜欢哦' AS answer, '送礼,长辈,陶瓷,推荐,预算' AS tags, '买家咨询陶瓷送长辈推荐' AS source_summary, 90 AS score
  UNION ALL SELECT 'handcraft_ceramic', '杯子有哪些款型？马克杯还是茶杯？', '亲，杯子有多种款型：第一种马克杯（带把手），适合咖啡、牛奶，办公室必备。第二种茶杯（无把手），适合品茶，手感温润。第三种茶盏（敞口浅杯），适合功夫茶。第四种咖啡杯（带碟），西式优雅。第五种随手杯（带盖带滤网），方便外出携带。每种款型有多种釉色和装饰可选。如果您平时喝咖啡，推荐马克杯；喝茶推荐茶杯或茶盏；办公室用推荐随手杯。也可以买套装搭配不同场景。不确定选什么可以告诉我您的使用习惯，帮您推荐哦' AS answer, '杯子,款型,马克杯,茶杯,选择' AS tags, '买家咨询杯子款型选择' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_ceramic', '陶瓷烧制会失败吗？失败了怎么办？', '亲，是的，陶瓷烧制有一定失败率，约10到15%哦。失败原因：烧制过程中开裂，因泥料或温度问题。釉面缺陷如缩釉、针孔。变形，因造型或烧制问题。窑变不可控，效果不理想。失败的作品我们会销毁或作为瑕疵品低价处理，不会发给客户。如果是定制款失败，我们会重新制作，工期顺延，但不会额外收费。制作过程会拍照发您确认每个阶段，出窑后也会拍照确认效果。虽然偶尔失败，但保证交付给您的都是满意的作品哦' AS answer, '陶瓷,烧制,失败,重做,品质' AS tags, '买家咨询陶瓷烧制失败处理' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_ceramic', '摆件有哪些系列？可以成套收藏吗？', '亲，我们的摆件有多个系列：第一种十二生肖系列，可以按生肖收藏。第二种福禄寿喜系列，传统文化题材。第三种萌宠系列，可爱动物造型。第四种禅意系列，佛教元素摆件。第五种节气系列，24节气主题。每个系列都有独特设计理念，可以单件购买，也可以成套收藏。成套购买有专属优惠和收藏证书。系列作品会持续推出新品，老客户优先购。手工陶瓷摆件既有艺术价值又有收藏价值，成套摆放更有气势，是家居装饰和收藏的好选择哦' AS answer, '摆件,系列,收藏,陶瓷,套装' AS tags, '买家咨询摆件系列及收藏' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_ceramic', '花瓶有礼盒装吗？送人怎么样？', '亲，花瓶有精美礼盒装哦！包装包含：定制泡沫定型加加厚纸盒加丝带加贺卡，确保运输安全和美观。礼盒装加10元（花瓶较大包装成本高），满300免费升级。送人特别合适，陶瓷花瓶既有艺术品味又实用，收礼人摆家里天天能看到，想起您的心意。适合送长辈、送朋友、乔迁礼物、结婚礼物。贺卡可以代写祝福语。如果是乔迁送花瓶加干花或仿真花套装，更有心意。送礼选陶瓷花瓶，有面子又有里子哦' AS answer, '花瓶,礼盒,送礼,包装,陶瓷' AS tags, '买家咨询花瓶礼盒及送礼' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_ceramic', '陶瓷杯子怎么保养？能用多久？', '亲，陶瓷杯子保养很简单哦。日常清洗：温水加中性洗涤剂，海绵或软布擦洗，避免钢丝球刮花釉面。茶渍咖啡渍可用小苏打或柠檬酸清洗。使用注意：避免骤冷骤热防止开裂；不要叠放防止磕碰；有金属装饰的不要微波。存放时杯口朝上，避免潮湿。正确保养的陶瓷杯可以用5到10年甚至更久，釉面依然光亮。我们的杯子釉面硬度高，正常使用不易有划痕。好杯子值得用心保养，每天喝水都是享受哦' AS answer, '杯子,保养,清洗,陶瓷,耐用' AS tags, '买家咨询杯子保养及寿命' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_ceramic', '我想定制一套茶具，多久能做好？', '亲，定制一套茶具（一壶六杯）工期约20到25天哦。流程：沟通需求确认设计（1到2天）。分别拉坯制作壶和杯子（5到7天）。晾干修坯（3到5天）。第一次素烧（2天）。上釉（1天）。第二次高温烧制（2天）。降温质检包装（2天）。每件茶具都需单独制作，所以比单品工期长。定制费用根据款式，简单款800到1500元，复杂款1500到3000元。制作过程会拍照确认。一套专属茶具，无论是自用还是送礼都特别有品位，值得等待哦' AS answer, '定制,茶具,工期,陶瓷,流程' AS tags, '买家咨询茶具定制周期' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_ceramic', '手工陶瓷有瑕疵正常吗？什么样的是瑕疵？', '亲，手工陶瓷因为是纯手工制作，会有一些手工痕迹，这和瑕疵是不同的哦。正常手工痕迹：釉面有微小气泡或针孔，是烧制自然现象。底部有修坯痕迹或窑痕。每件颜色略有差异，是窑变特性。形状有轻微不对称，是手作特点。这些不影响使用，反而体现手作独特性。但以下属于瑕疵我们会避免：明显开裂或破损。釉面大面积脱落。严重变形影响使用。把手松动。发货前严格质检，有瑕疵不会发出。您可以放心购买哦' AS answer, '陶瓷,瑕疵,手工,质检,正常' AS tags, '买家咨询陶瓷瑕疵及质检标准' AS source_summary, 85 AS score
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

-- ============ 5. 木工作品 handcraft_wood (30条) ============
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.61', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'handcraft_wood' AS code, '这个木工作品是什么木材的？硬度怎么样？' AS question, '亲，这款作品采用优质胡桃木制作哦，硬度适中、纹理美观、耐腐蚀性好。胡桃木是中高端木材，颜色温润有质感，适合做家具、摆件、文具等。我们还有其他木材可选：黑胡桃（深色高级）、樱桃木（温润红润）、橡木（坚硬耐用）、松木（经济轻便）、榉木（细腻稳定）。不同木材特点不同，价格也有差异。如果您对木材有偏好或用途特殊，可以咨询客服推荐最合适的木材。手工木作选对木材，作品质感翻倍哦' AS answer, '木材,胡桃木,硬度,选择,木工' AS tags, '买家咨询木材种类及硬度' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_wood', '木工作品上漆吗？环保吗？', '亲，我们使用环保木蜡油处理，不是化学漆哦。木蜡油是天然植物油提取，无毒无异味，通过环保认证，可以放心使用。木蜡油能渗透进木材内部，保护木材同时保留天然纹理和触感，相比化学漆更环保、更有质感。处理后木材防水防污，日常使用不易脏。如果您需要更高光泽度，可以选擦漆款，用天然虫漆，也是环保材料。儿童用品我们使用食品级木蜡油，更安全。环保处理虽然成本高，但用得放心哦' AS answer, '木工,上漆,环保,木蜡油,安全' AS tags, '买家咨询木工上漆及环保性' AS source_summary, 88 AS score
  UNION ALL SELECT 'handcraft_wood', '这个木质小板凳能承重多少？成人能坐吗？', '亲，这款小板凳采用榫卯结构加胡桃木制作，承重150kg没问题，成人完全可以坐哦。凳面厚3cm，凳腿直径4cm，结构稳固不摇晃。尺寸30乘20乘25cm，便携轻巧。相比塑料凳，木凳更耐用、更有质感、承重更好。我们还有大号款35乘25乘30cm，承重200kg，适合体型较大的用户。如果您需要做餐椅或工作凳，推荐加厚款。每个凳子都经过承重测试，确保安全。手工木凳结实耐用，用几十年都没问题哦' AS answer, '木工,承重,板凳,榫卯,耐用' AS tags, '买家咨询木质家具承重' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_wood', '这个木质摆件多大？放哪里合适？', '亲，这款摆件尺寸20乘15乘10cm，重量约500g，放书桌、办公桌、茶几、展示柜都合适。还有小号15cm和大号25cm可选。小号适合放书桌、床头，精致点缀；中号最百搭，各种位置都适合；大号适合客厅、玄关等大空间。摆件底部有防滑毡垫，放稳不刮桌面。胡桃木材质有天然纹理，每件独一无二。如果您有特定摆放空间，可以先量好尺寸再选，或者发照片给我帮您推荐。手工木摆件能瞬间提升空间格调哦' AS answer, '摆件,尺寸,木质,摆放,选择' AS tags, '买家咨询木摆件尺寸及摆放' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_wood', '这个木质模型精度怎么样？比例多少？', '亲，这款木质模型精度很高哦，采用激光切割加手工打磨，误差控制在0.5mm以内。比例1:24，还原真实细节。零件数约50个，组装后尺寸25乘15乘15cm。适合做收藏摆件或教学演示。我们还有不同比例可选：1:12大比例细节更丰富，1:48小比例更便携。模型采用榫卯结构拼接，不需要胶水，可以反复拆装。如果您是模型爱好者，推荐进阶款，零件更多、细节更精致。手工木质模型既有艺术性又有把玩性，值得收藏哦' AS answer, '模型,精度,比例,木质,组装' AS tags, '买家咨询木质模型精度及比例' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_wood', '这个木桌能定制尺寸吗？我想要小一号的。', '亲，木桌可以定制尺寸哦！我们有标准尺寸80乘60乘40cm，也可以根据您需求定制。定制流程：沟通尺寸和款式。报价确认。制作（7到15天）。拍照确认。发货。定制费用根据尺寸和复杂度，一般加10到30%费用。如果是大幅尺寸变化，相当于重新设计，费用会更高。建议定制前先量好您家的空间尺寸，留出余量。如果是定制款不支持退换，制作过程会拍照确认。手作木桌量身定制，做出来更合身，用着更舒心哦' AS answer, '定制,尺寸,木桌,木工,流程' AS tags, '买家咨询木桌定制尺寸' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_wood', '木质作品怎么保养？会开裂吗？', '亲，木质作品保养得当不会开裂哦。保养建议：避免阳光直射和暖气旁，防止干燥开裂。避免潮湿环境，防止变形发霉。定期用木蜡油或核桃油擦拭保养，每3到6个月一次。清洁用干布或微湿布，不要水洗。避免磕碰和划伤。开裂原因主要是环境湿度变化大，建议保持室内湿度40到60%。北方冬天干燥可以放加湿器。我们的木材都经过烘干处理，含水率控制在8到12%，降低开裂风险。正确保养，木作能传代哦' AS answer, '木材,保养,开裂,湿度,木蜡油' AS tags, '买家咨询木材保养及开裂' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_wood', '木质作品怎么包装？运输安全吗？', '亲，木工作品包装很用心哦！包装流程：珍珠棉包裹，气泡膜防震，泡沫定型，加厚瓦楞纸箱，防撞角保护。每件作品包装前检查无瑕疵，包装过程拍照留档。木工作品相比陶瓷不易碎，但也要防磕碰和划伤。小件走快递，大件走物流。发货后有单号可查。万一运输损坏，我们免费补发或退款。收到后请当面验货，如有问题48小时内联系客服。我们的运输破损率控制在1%以下，您可以放心购买哦' AS answer, '木工,包装,运输,安全,防震' AS tags, '买家咨询木工包装及运输' AS source_summary, 84 AS score
  UNION ALL SELECT 'handcraft_wood', '木工作品多久能做好？为什么比陶瓷快？', '亲，木工作品工期一般7到15天哦，比陶瓷快因为不需要烧制等待。流程：选材沟通（1天）。切割开料（1到2天）。雕刻或榫卯制作（2到5天）。打磨（1到2天）。上木蜡油（1天）。晾干包装（1到2天）。复杂作品如家具可能需要15到20天。现货款24小时内发货。定制款根据复杂度7到15天。如果您急用，可以选现货款或咨询加急，简单款3天能做好。木工作品制作周期适中，值得等待，收到成品时一定觉得值得哦' AS answer, '木工,工期,制作,流程,陶瓷' AS tags, '买家咨询木工工期及流程' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_wood', '这个木制玩具给婴儿玩安全吗？', '亲，我们儿童木制玩具使用食品级木蜡油处理，通过儿童玩具安全检测，婴儿可以放心使用哦。特点：木材选用优质榉木，无毛刺不伤手。食品级木蜡油，即使宝宝啃咬也安全。无小零件，避免误吞风险。边角全部圆角处理。颜色使用环保水性颜料。尺寸适合宝宝抓握。我们也有专门的婴儿系列，适合6个月以上。如果您给宝宝使用，建议选择无配件款。安全第一，我们的儿童木作都经过严格检测，您可以放心购买哦' AS answer, '婴儿,安全,木制,玩具,检测' AS tags, '买家咨询木制玩具婴儿安全' AS source_summary, 90 AS score
  UNION ALL SELECT 'handcraft_wood', '木材是哪里产的？是进口的吗？', '亲，我们的木材来自国内外优质产区哦。胡桃木主要来自北美进口，颜色深纹理美；樱桃木来自北美或日本，温润红润；橡木来自欧洲或国产，坚硬耐用；榉木来自德国或国产，细腻稳定；松木国产为主，经济轻便。所有木材都经过FSC认证（可持续林业），合法采伐。入库前经过烘干处理，含水率控制在8到12%，确保稳定不易变形。如果您对产地有要求，可以咨询客服推荐。优质木材是手作木工的基础，我们坚持用好料哦' AS answer, '木材,产地,进口,认证,烘干' AS tags, '买家咨询木材产地及来源' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_wood', '这个木桌是榫卯结构吗？需要胶水吗？', '亲，是的，我们的木家具采用传统榫卯结构，不用胶水和钉子哦。榫卯是中华传统木工技艺，通过木材本身的凹凸结构连接，牢固耐用，可以反复拆装。相比胶水拼接，榫卯结构更环保、更耐用、更有工艺价值。我们的榫卯经过精密计算和手工修整，接缝紧密不松动。如果您需要可拆卸款，可以选可拆榫卯，搬家方便；固定款用死榫，更稳固。传统榫卯木作不仅是家具，更是文化传承，值得拥有哦' AS answer, '榫卯,结构,木工,传统,环保' AS tags, '买家咨询榫卯结构及工艺' AS source_summary, 89 AS score
  UNION ALL SELECT 'handcraft_wood', '这个木桌多重？搬动方便吗？', '亲，这款木桌采用胡桃木实木，重量约15kg，搬动需要两人配合哦。相比板材家具，实木更重但更稳固耐用。桌面厚3cm，桌腿粗4cm，结构扎实不摇晃。如果您需要轻便款，可以选松木材质，重量减半但承重稍弱；或者选空心设计款，重量减轻但保持强度。大件家具建议固定位置摆放，避免频繁搬动。搬运时不要拖拽，抬起移动防止刮花地板和桌腿。实木家具虽然重，但用几十年没问题，传代都有可能哦' AS answer, '木桌,重量,搬运,实木,耐用' AS tags, '买家咨询木桌重量及搬运' AS source_summary, 83 AS score
  UNION ALL SELECT 'handcraft_wood', '摆件上的图案是雕刻的吗？能定制图案吗？', '亲，摆件图案是手工雕刻加激光雕刻结合哦，细节精致有层次。可以定制图案，比如名字、日期、简单图形、logo等。定制流程：发图评估可行性。确认设计和报价。制作（5到7天）。拍照确认。定制费用根据图案复杂度，简单图形20到50元，复杂图案50到200元。雕刻深度0.5到2mm，清晰永久。如果是复杂人像或风景，建议简化为线条风或剪影风，效果更好。定制木作独一无二，送人特别有心意，赶紧定制一个吧' AS answer, '摆件,雕刻,定制,图案,木工' AS tags, '买家咨询摆件雕刻及定制' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_wood', '木质模型需要自己组装吗？难度大吗？', '亲，木质模型有两种款：成品款和DIY组装款。成品款收到即用，适合收藏摆件。DIY组装款需要自己拼装，包含所有零件、工具、说明书，适合动手爱好者。组装难度分三级：初级（50零件以内，1到2小时），中级（50到100零件，3到5小时），高级（100加零件，5到10小时）。建议新手从初级开始，循序渐进。组装过程有图文和视频教程，也有在线答疑。组装完成的成就感爆棚，是很好的亲子活动和减压方式哦' AS answer, '模型,组装,DIY,难度,教程' AS tags, '买家咨询模型组装及难度' AS source_summary, 88 AS score
  UNION ALL SELECT 'handcraft_wood', '木工作品能刻字吗？能刻多大？', '亲，可以刻字哦！采用激光雕刻，精度高、效果清晰、永久不掉。刻字内容可以是名字、日期、祝福语、简笔画等。中文最多刻30字，英文50字符。刻字尺寸根据作品大小调整，一般2到5cm高。刻字费10到30元根据字数和复杂度。下单时备注刻字内容、字体偏好（楷体、宋体、英文体、手写体）、位置。也可以刻logo或简单图案，先发图评估。刻字款让作品独一无二，送人特别有心意。木质刻字效果比陶瓷更精致，推荐试试哦' AS answer, '刻字,定制,木工,激光,礼物' AS tags, '买家咨询木工刻字定制' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_wood', '木工作品送男生什么好？预算200左右。', '亲，200左右送男生推荐几款特别合适的哦。第一款是胡桃木桌面收纳盒，实用有格调，168元办公室必备。第二款是木质手表架加眼镜架套装，男生日常用得到，158元。第三款是手工木质钢笔，质感高级，188元送笔送文化。第四款是木质模型DIY套装，动手又有趣，178元适合模型控。所有礼品都可以刻字定制，配礼盒和贺卡，代写祝福。送男生选木作既有品味又实用，男生一定喜欢。现在下单还送精美礼品袋哦' AS answer, '送礼,男生,木工,推荐,预算' AS tags, '买家咨询木工送男生推荐' AS source_summary, 90 AS score
  UNION ALL SELECT 'handcraft_wood', '木材含水率多少？会变形吗？', '亲，我们的木材含水率控制在8到12%哦，经过专业烘干处理，达到家具级标准。含水率是木材稳定性的关键指标，过高容易变形开裂，过低容易脆裂。8到12%适合全国大部分地区使用。北方干燥地区建议选含水率偏低的（8到10%），南方潮湿地区建议选偏高的（10到12%）。我们的木材入库前会测含水率，不合格不使用。成品也会在恒温恒湿环境静置一周，确保稳定后再发货。正确保养的话，变形风险很低，您可以放心购买哦' AS answer, '木材,含水率,变形,烘干,稳定' AS tags, '买家咨询木材含水率及变形' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_wood', '能定制整套家具吗？工期多久？', '亲，可以定制整套家具哦！我们承接各类木家具定制：餐桌椅、书桌、收纳柜、茶几、床架等。定制流程：沟通需求和预算。上门量尺（本地）或提供尺寸（异地）。出设计图和报价。确认后支付定金开始制作。制作工期30到45天根据数量。完工拍照确认。付尾款发货或上门安装。定制费用根据木材、尺寸、工艺，普通款3000到8000元每件，高端款上万元。整套定制有专属优惠。手工实木家具用几十年没问题，值得投资哦' AS answer, '家具,定制,整套,工期,实木' AS tags, '买家咨询整套家具定制' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_wood', '摆件有哪些系列？可以成套收藏吗？', '亲，我们的木摆件有多个系列：第一种十二生肖系列，按生肖收藏。第二种福禄寿喜系列，传统题材。第三种山水风景系列，自然主题。第四种抽象艺术系列，现代设计。第五种节气系列，24节气主题。每个系列都有独特设计，可以单件购买，也可以成套收藏。成套购买有专属优惠和收藏证书。每件摆件都带作者签名和编号，有收藏价值。系列作品会持续推出，老客户优先购。手工木摆件既有艺术价值又有收藏价值，成套摆放更有气势，值得珍藏哦' AS answer, '摆件,系列,收藏,木工,套装' AS tags, '买家咨询摆件系列及收藏' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_wood', '木质模型有哪些款型？什么难度？', '亲，木质模型有多种款型：第一种建筑模型（房子、城堡、桥），难度中级。第二种交通工具（汽车、飞机、船），难度中高级。第三种机械模型（齿轮、时钟、机关），难度高级。第四种动物模型（恐龙、昆虫、海洋生物），难度初级到中级。第五种乐器模型（钢琴、吉他、小提琴），难度高级。每款都标注零件数和组装时间，方便选择。新手推荐动物或简单建筑入门，进阶选交通工具，高手挑战机械模型。DIY过程既动手又动脑，完成后超有成就感哦' AS answer, '模型,款型,难度,木质,DIY' AS tags, '买家咨询模型款型及难度' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_wood', '新手买木工作品，什么木材性价比高？', '亲，新手推荐几款性价比高的木材哦。松木：最便宜，质地轻软易加工，适合练手和小摆件，但硬度低易有划痕。榉木：性价比之王，硬度适中、纹理细腻、价格亲民，适合做家具和摆件。橡胶木：经济实惠，稳定性好，适合做桌面和板材。如果预算充足推荐樱桃木和胡桃木，质感更好。黑胡桃最贵但最高级。建议新手从松木或榉木入门，熟练后再用高端木材。我们也有木材样板出售，9.9元6种木材小样，可以先感受再决定哦' AS answer, '木材,选择,新手,性价比,推荐' AS tags, '买家咨询木材选择及性价比' AS source_summary, 88 AS score
  UNION ALL SELECT 'handcraft_wood', '买木工作品送工具吗？后续自己能修吗？', '亲，成品本身不附赠工具哦，但小修小补我们可以免费帮您处理。比如表面划痕可以寄回来重新打磨上油，松动可以重新加固，这些小问题都免费服务。如果您想自己动手，推荐基础工具套装：砂纸、木锉、手钻、凿子、木蜡油，约80元够用了。也可以买DIY材料包自己做一个，更有成就感。我们的作品做工扎实，正常使用不易损坏，但万一有问题随时联系我，售后有保障。手作木工的乐趣也在于自己动手，欢迎入坑哦' AS answer, '工具,维修,售后,木工,DIY' AS tags, '买家咨询木工工具及维修' AS source_summary, 82 AS score
  UNION ALL SELECT 'handcraft_wood', '这个木摆件多重？放书架会压弯吗？', '亲，这款摆件约500g，放书架完全没问题，不会压弯哦。书架层板一般承重10到20kg，一个摆件500g很轻松。我们还有小号300g和大号800g可选。如果您担心书架承重，可以选小号或分散摆放。摆件底部有防滑毡垫，放稳不滑动不刮花。胡桃木密度适中，既有质感又不会过重。如果您要做大型摆件组合，建议选轻质木材如松木，重量更轻。手工木摆件重量适中，摆放稳定，是书架装饰的好选择哦' AS answer, '摆件,重量,书架,承重,木工' AS tags, '买家咨询摆件重量及书架承重' AS source_summary, 81 AS score
  UNION ALL SELECT 'handcraft_wood', '木质模型的材料环保吗？有味道吗？', '亲，模型材料是环保木材加无毒胶水，没有刺鼻味道哦。木材选用经过烘干的优质胶合板或实木，含水率适中不易变形。胶水是环保水性胶，通过检测无毒无异味。颜料是环保水性颜料，色彩鲜艳不褪色。组装时不需要额外胶水（榫卯结构），但部分精细零件可能需要少量胶水固定，我们附带环保胶。新作品打开可能有轻微木香味，这是木材天然味道，通风1到2天就消失了。环保材料虽然成本高，但用得放心，特别是给孩子的模型哦' AS answer, '模型,材料,环保,味道,安全' AS tags, '买家咨询模型材料环保性' AS source_summary, 86 AS score
  UNION ALL SELECT 'handcraft_wood', '木桌有哪些款式？什么风格？', '亲，木桌有多种款式：第一种简约现代风，线条简洁，适合北欧家居。第二种中式古典风，雕花榫卯，适合传统装修。第三种日式极简风，低矮禅意，适合榻榻米。第四种工业复古风，铁木结合，适合loft。第五种原木自然风，保留树皮和自然边，个性十足。每种款式有多种木材和尺寸可选。如果您家居是北欧风格，推荐简约现代加白橡木；中式风格选古典加胡桃木；日式选极简加榉木。不确定选什么，发家居照片给我，帮您推荐最合适的款式和木材哦' AS answer, '木桌,款式,风格,选择,搭配' AS tags, '买家咨询木桌款式及风格' AS source_summary, 85 AS score
  UNION ALL SELECT 'handcraft_wood', '这个木摆件有什么寓意？送人合适吗？', '亲，每件木摆件都有独特寓意哦。比如这款葫芦摆件，寓意福禄，送长辈或开业佳选；这款鱼形摆件寓意年年有余，新年礼物合适；这款如意摆件象征万事如意，送升职乔迁有意义；这款貔貅摆件寓意招财进宝，送生意人受欢迎。木材本身也有寓意：胡桃木象征坚韧，樱桃木象征温暖，檀木象征尊贵。如果您有特定送礼场景，告诉我对象和场合，我推荐最合适的摆件，还能附赠寓意卡片。手工木摆件送人特别有品味哦' AS answer, '摆件,寓意,送礼,木工,推荐' AS tags, '买家咨询摆件寓意及送礼' AS source_summary, 88 AS score
  UNION ALL SELECT 'handcraft_wood', '模型组装有教程吗？看不懂怎么办？', '亲，每套模型都配详细教程哦！包含：图文说明书，每个步骤有高清图和文字说明。视频教程，扫码观看，老师边做边讲。零件清单图，方便核对。常见问题解答。在线答疑群，有问题随时问。教程按步骤编号，跟着做就行。新手建议从初级模型开始，熟练后再挑战高难度。如果您做到某一步卡住了，可以拍照发群里，老师会指导。组装过程也是享受的过程，不急不躁，慢慢做出作品，成就感爆棚哦' AS answer, '模型,教程,组装,新手,答疑' AS tags, '买家咨询模型教程及答疑' AS source_summary, 89 AS score
  UNION ALL SELECT 'handcraft_wood', '定制木工作品流程是怎样的？怎么付款？', '亲，定制流程如下：沟通需求，发参考图或描述想法。我出设计图和报价。确认后支付50%定金。开始制作，过程中拍照发您确认。完工拍照确认效果。支付尾款50%。包装发货。工期根据复杂度7到30天。定制款不支持退换，但制作过程会充分沟通确认，确保符合预期。如果中途想修改设计，在制作前可以免费改，制作中改可能需要补费。付款支持闲鱼担保交易，安全有保障。手作定制独一无二，值得期待哦' AS answer, '定制,流程,付款,木工,沟通' AS tags, '买家咨询木工定制流程及付款' AS source_summary, 87 AS score
  UNION ALL SELECT 'handcraft_wood', '手工木工作品有收藏价值吗？', '亲，手工木工作品是有收藏价值的哦，特别是以下几个方向：第一种名家作品，有作者签名和证书，升值空间大。第二种稀有木材，如黄花梨、小叶紫檀、沉香木，材质本身珍贵。第三种精品工艺，如复杂榫卯、精细雕刻、独特设计。第四种限量版，编号发行，稀缺性高。第五种系列作品，成套收藏更有价值。我们的高端系列都带作者签名和收藏证书，部分限量发行。木作收藏既是投资也是审美享受，好的木作会越用越有味道，越藏越有价值。值得入手收藏哦' AS answer, '收藏,木工,价值,名家,限量' AS tags, '买家咨询木作收藏价值' AS source_summary, 89 AS score
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;
